window.__CH("c20",["<div class=\"hw\">N, n</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第13字.</div>\r\n","<div class=\"hw\">N., n.</div><div class=\"def\">《略》=<a href=\"entry://Numerius\">Numerius</a>;<a href=\"entry://Nōnae\">Nonae</a>;<a href=\"entry://nātiō\">natio</a>;<a href=\"entry://nātus\">natus</a>;<a href=\"entry://nepōs\">nepos</a>;<a href=\"entry://nihilum\">nihilum</a>;<a href=\"entry://numerus\">numerus</a>;<a href=\"entry://nummus\">nummus</a>.</div>\r\n","<div class=\"hw\">Nabataea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナバタエア, <SUP>*</SUP>-タイアー《Nabataei 族の国》.</div>\r\n","<div class=\"hw\">Nabataeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Nabataei 族の, Nabataea の.</div><div class=\"def\"><num>②</num> 《詩》Arabia の;東方の.</div>\r\n","<div class=\"hw\">Nabataeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナバタエイー, <SUP>*</SUP>-タイオイ《Arabia 北部にいた一部族》.</div>\r\n","<div class=\"hw\">Nabis</div><div class=\"pos\">-idis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナビス《残虐で有名な Sparta の王(前207‐192)》.</div>\r\n","<div class=\"hw\">nablia</div><div class=\"pos\">-ium, <i>n</i><i>pl</i></div><div class=\"ori\">[<i>Gk</i><<i>Sem</i>.]</div><div class=\"def\">竪琴の一種.</div>\r\n","<div class=\"hw\">nactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nanciscor\">nanciscor</a>.</div>\r\n","<div class=\"hw\">nae</div><div class=\"pos\"><i>int</i></div><div class=\"def\">=<a href=\"entry://nē\">ne<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">naenia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://nēnia\">nenia</a>.</div>\r\n","<div class=\"hw\">Naevius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ナエウィウス《ローマ人の氏族名;特に <i>Cn. ～</i>, 前3世紀のローマの詩人・劇作家》.</div><hr><div class=\"hw\">Naevius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Naevius の.</div>\r\n","<div class=\"hw\">Naeviānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Naevius の.</div>\r\n","<div class=\"hw\">naevulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://naevus\">naevus</a>]</div><div class=\"def\">(小さな)ほくろ, あざ.</div>\r\n","<div class=\"hw\">naevus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ほくろ, あざ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 汚点.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘医〙母斑.</div>\r\n","<div class=\"hw\">Naha(na)rvālī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ナハナルウァーリー《Germania 北東部にいた Ligii 族の一支族》.</div>\r\n","<div class=\"hw\">nam</div><div class=\"pos\"><i>conj</i></div><div class=\"def\"><num>①</num> というのも, なぜなら.</div><div class=\"def\"><num>②</num> もちろん, 確かに.</div><div class=\"def\"><num>③</num> 一方, それでは.</div><div class=\"def\"><num>④</num> たとえば.</div><div class=\"def\"><num>⑤</num> (前接辞として疑問の意を強める)いったい</div><div class=\"ex\"><i>quisnam</i><span class=\"ext\">いったい誰が</span></div><div class=\"ex\"><i>ubinam</i><span class=\"ext\">いったいどこに.</span></div>\r\n","<div class=\"hw\">Namnētēs</div><div class=\"pos\">-um, <i>pl</i></div><div class=\"def\">ナムネーテース《Gallia Celtica の現 Nantes 付近にいた一部族》.</div>\r\n","<div class=\"hw\">namque</div><div class=\"pos\"><i>conj</i></div><div class=\"ori\">[nam/-que<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> もちろん, 確かに.</div><div class=\"def\"><num>②</num> というのも.</div><div class=\"def\"><num>③</num> たとえば.</div>\r\n","<div class=\"hw\">nancior</div><div class=\"pos\">-īrī, <i>tr dep</i></div><div class=\"def\">=<a href=\"entry://nanciō\">nancio</a>.</div>\r\n","<div class=\"hw\">nanciscor</div><div class=\"pos\">-scī nactus [nanctus] sum, <i>tr dep inch</i></div><div class=\"ori\">[nancio]</div><div class=\"def\"><num>①</num> 手に入れる, 獲得する.</div><div class=\"def\"><num>②</num> 着く, 到着する.</div><div class=\"def\"><num>③</num> (偶然)見つける, でくわす.</div>\r\n","<div class=\"hw\">nanciscī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://nanciscor\">nanciscor</a>.</div>\r\n","<div class=\"hw\">nanciō</div><div class=\"pos\">-īre, <i>tr</i></div><div class=\"def\">獲得する, 手に入れる.</div>\r\n","<div class=\"hw\">nanctus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">=<a href=\"entry://nactus\">nactus</a>.</div>\r\n","<div class=\"hw\">nans</div><div class=\"pos\">nantis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[no]</div><div class=\"def\">(鳥・動物が)遊泳性の, 泳ぐ.</div>\r\n","<div class=\"hw\">Nantuātēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">ナントゥアーテース《Gallia Narbonensis にいた一部族》.</div>\r\n","<div class=\"hw\">Napaeae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[↓<a href=\"entry://napaeus\">napaeus</a>]</div><div class=\"def\">〘神話〙ナパエアエ, <SUP>*</SUP>ナパイアイ《谷間の森に住むニンフたち》.</div>\r\n","<div class=\"hw\">napaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">谷間の森の.</div>\r\n","<div class=\"hw\">naphtha</div><div class=\"pos\">-ae, <i>f</i>, <B>napht(h)ās</B> -ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナフサ.</div>\r\n","<div class=\"hw\">naphthalīnum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://naphtha\">naphtha</a>]</div><div class=\"def\">〘化〙ナフタリン.</div>\r\n","<div class=\"hw\">Narbō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ナルボー《Gallia Narbonensis の主要な町;～ Martius とも呼ばれた;現 Narbonne》.</div>\r\n","<div class=\"hw\">Narbōna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://Narbō\">Narbo</a>.</div>\r\n","<div class=\"hw\">Narbōnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Narbo の</div><div class=\"ex\"><i>Gallia</i> ～<span class=\"ext\">(⇒ <a href=\"entry://Gallia\">Gallia</a>).</span></div>\r\n","<div class=\"hw\">narcissus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙スイセン(水仙).</div>\r\n","<div class=\"hw\">Narcissus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナルキッスス, <SUP>*</SUP>-ソス《 (1) 〘神話〙Cephisus 河神とニンフ Liriope の息子;泉に映る自分の姿に恋いこがれ, 水仙の花になった.(2) Claudius 帝の富裕な解放奴隷》.</div>\r\n","<div class=\"hw\">narcōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘医〙麻酔.</div>\r\n","<div class=\"hw\">narcōticum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://narcōticus\">narcōticus</a>]</div><div class=\"def\">〘薬〙麻酔薬;麻薬.</div>\r\n","<div class=\"hw\">narcōticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">麻酔性の.</div>\r\n","<div class=\"hw\">nardinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nardinus\">nardinus</a>]</div><div class=\"def\">(<i>sc</i>. vinum)カンショウ(甘松)の香りをつけたぶどう酒.</div>\r\n","<div class=\"hw\">nardinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nardus\">nardus</a>]</div><div class=\"def\">カンショウの.</div>\r\n","<div class=\"hw\">nardus</div><div class=\"pos\">-ī, <i>f</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙カンショウ(甘松).</div><div class=\"def\"><num>②</num> 甘松香.</div>\r\n","<div class=\"hw\">Naristī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ナリスティー《Germania の Suebi 族の一支族》.</div>\r\n","<div class=\"hw\">Narnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ナルニア《Umbria の Nar 河畔の町;現 Narni》.</div>\r\n","<div class=\"hw\">Narniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Narnia の.</div><div class=\"hw2\"><b>Narniensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Narnia の住民.</div>\r\n","<div class=\"hw\">narrābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[narro]</div><div class=\"def\">語ることができる.</div>\r\n","<div class=\"hw\">narrātiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://narrātiō\">narrātiō</a>]</div><div class=\"def\">(ちょっとした)話.</div>\r\n","<div class=\"hw\">narrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[narro]</div><div class=\"def\"><num>①</num> 物語, 話, 語り.</div><div class=\"def\"><num>②</num> 〘修〙陳述《古典的弁論形式において問題の経緯を述べる段階》.</div>\r\n","<div class=\"hw\">narrātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[narro]</div><div class=\"def\">語り手.</div>\r\n","<div class=\"hw\">narrātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://narrātus\">narrātus<SUP>1</SUP></a>]</div><div class=\"def\">語られたこと, 物語.</div>\r\n","<div class=\"hw\">narrātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://narrō\">narro</a>.</div><hr><div class=\"hw\">narrātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">物語, 話, 語り.</div>\r\n","<div class=\"hw\">narrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[<i>cf</i>. gnarus]</div><div class=\"def\"><num>①</num> 話す, 語る, 物語る 〈+<i>acc c</i>. <i>inf</i>;+間接疑問〉.</div><div class=\"def\"><num>②</num> 言う, 述べる.</div>\r\n","<div class=\"hw\">narthex</div><div class=\"pos\">-ēcis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙オオウイキョウ.</div>\r\n","<div class=\"hw\">narthēcium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">薬瓶, 軟骨入れ.</div>\r\n","<div class=\"hw\">Narōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ナローナ《Dalmatia の町》.</div>\r\n","<div class=\"hw\">Nasamōnes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナサモーネス《Libya にいた一部族》.</div>\r\n","<div class=\"hw\">Nasamōniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Nasamones 族の;《詩》Africa の.</div>\r\n","<div class=\"hw\">Nasamōnias</div><div class=\"pos\">-adis, <i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Nasamones 族の.</div>\r\n","<div class=\"hw\">Nasamōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nasamones 族の;《詩》Africa の, Libya の.</div>\r\n","<div class=\"hw\">nascens</div><div class=\"pos\">-ntis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[nascor]</div><div class=\"def\">生まれたばかりの, 初期の.</div>\r\n","<div class=\"hw\">nascentia<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://nascens\">nascens</a>]</div><div class=\"def\">誕生.</div><hr><div class=\"hw\">nascentia<SUP>2</SUP></div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"def\">植物.</div>\r\n","<div class=\"hw\">nascor</div><div class=\"pos\">-scī nātus sum, <i>intr dep</i></div><div class=\"ori\">[<i>cf. </i> gigno]</div><div class=\"def\"><num>①</num> 生まれる, 誕生する.</div><div class=\"def\"><num>②</num> 生ずる, 起こる, 発生する.</div><div class=\"def\"><num>③</num> (天体が)昇る;夜が明ける.</div>\r\n","<div class=\"hw\">nascī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://nascor\">nascor</a>.</div>\r\n","<div class=\"hw\">nassa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (魚を捕るための)枝編みのわな, やな.</div><div class=\"def\"><num>②</num> わな, 計略.</div>\r\n","<div class=\"hw\">nasturcium, -tium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙コショウソウ, オランダガラシ.</div>\r\n","<div class=\"hw\">natans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[nato]</div><div class=\"def\"><num>①</num> (海で)泳いでいる, 海にすむ.</div><div class=\"def\"><num>②</num> (波が)上下する, 波立つ.</div>\r\n","<div class=\"hw\">natantēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[↑<a href=\"entry://natans\">natans</a>]</div><div class=\"def\">《詩》泳ぐもの(=魚).</div>\r\n","<div class=\"hw\">natis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">(主に <i>pl</i>)臀部, 尻.</div>\r\n","<div class=\"hw\">natrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ナトリウム</div><div class=\"ex\">～ <i>carbonicum</i><span class=\"ext\">炭酸ナトリウム</span></div><div class=\"ex\">～ <i>jodatum</i><span class=\"ext\">ヨード・ナトリウム</span></div><div class=\"ex\">～ <i>nitricum</i><span class=\"ext\">硝酸ナトリウム.</span></div>\r\n","<div class=\"hw\">natrix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"def\">〘動〙水ヘビ.</div>\r\n","<div class=\"hw\">natātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nato]</div><div class=\"def\"><num>①</num> 泳ぐこと.</div><div class=\"def\"><num>②</num> 遊泳地[施設].</div>\r\n","<div class=\"hw\">natātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[nato]</div><div class=\"def\">泳ぐ人.</div>\r\n","<div class=\"hw\">natātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://natō\">nato</a>.</div>\r\n","<div class=\"hw\">natātōria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i>, <B>-um</B> -ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://natātōrius\">natātōrius</a>]</div><div class=\"def\">泳ぐ場所.</div>\r\n","<div class=\"hw\">natātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[natator]</div><div class=\"def\">泳ぐための.</div>\r\n","<div class=\"hw\">natēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">⇒<a href=\"entry://natis\">natis</a>.</div>\r\n","<div class=\"hw\">natō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)<i>freq</i></div><div class=\"ori\">[no]</div><div class=\"def\"><num>①</num> 泳ぐ.</div><div class=\"def\"><num>②</num> 浮かぶ, 漂う.</div><div class=\"def\"><num>③</num> 浸る, つかる 〈re〉.</div><div class=\"def\"><num>④</num> 揺れ動く, 動きまわる</div><div class=\"ex\"><i>ante oculos natant tenebrae</i> (<author>O<small>V</small></author>)<span class=\"ext\">目の前がまっ暗になる.</span></div><div class=\"def\"><num>⑤</num> (目が)とろんとしている, うつろである.</div><div class=\"def\"><num>⑥</num> (心が)動揺する, ぐらつく.</div>\r\n","<div class=\"hw\">nauarchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船長, 艦長.</div>\r\n","<div class=\"hw\">Naubolidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Naubolus の息子(=<a href=\"entry://īphitus\">Iphitus</a>).</div>\r\n","<div class=\"hw\">Naubolus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ナウボルス, <SUP>*</SUP>-ロス《Phocis の王;Argonautae の一人である Iphitus の父》.</div>\r\n","<div class=\"hw\">nauclēricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船長の.</div>\r\n","<div class=\"hw\">nauclērus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船長.</div>\r\n","<div class=\"hw\">Naucratēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナウクラテース《ギリシアの史家(前4世紀後半);Isocrates の弟子》.</div>\r\n","<div class=\"hw\">naucum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"def\">取るに足らぬもの, くだらぬもの</div><div class=\"ex\"><i>non nauci esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">取るに足らない, 値打がない.</span></div>\r\n","<div class=\"hw\">naufragium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[naufragus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 難船, 難破.</div><div class=\"def\"><num>②</num> 失敗, 破滅.</div><div class=\"def\"><num>③</num> (難破船の)残骸.</div>\r\n","<div class=\"hw\">naufragus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[navis/frango]</div><div class=\"def\"><num>①</num> 難船[難破]した;難船の.</div><div class=\"def\"><num>②</num> 破滅した.</div><div class=\"def\"><num>③</num> 難船させる.</div><hr><div class=\"hw\">naufragus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">難船者.</div>\r\n","<div class=\"hw\">naufragō</div><div class=\"pos\">-āre -āvī, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://naufragus\">naufragus<SUP>1</SUP></a>]</div><div class=\"def\">難船する.</div>\r\n","<div class=\"hw\">naulum, -on</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船賃, 渡し賃.</div>\r\n","<div class=\"hw\">naumachia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (見世物としての)模擬海戦.</div><div class=\"def\"><num>②</num> 模擬海戦場《見世物のためにローマ市内に作られた人口湖》.</div>\r\n","<div class=\"hw\">naumachiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://naumachia\">naumachia</a>]</div><div class=\"def\">模擬海戦場の.</div><hr><div class=\"hw\">naumachiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">模擬海戦参加者.</div>\r\n","<div class=\"hw\">Naupactus, -os</div><div class=\"pos\">-ī, <i>f</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナウパクトゥス, <SUP>*</SUP>-トス《Corinthus 湾に面する Aetolia の町;現 Návpaktos》.</div>\r\n","<div class=\"hw\">Naupactōus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Naupactus の.</div>\r\n","<div class=\"hw\">naupathīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">船酔い.</div>\r\n","<div class=\"hw\">Naupliadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Nauplius の息子(=<a href=\"entry://Palamēdēs\">Palamedes</a>).</div>\r\n","<div class=\"hw\">Nauplius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ナウプリウス, <SUP>*</SUP>-オス《Euboea の王;息子 Palamedes の復讐のためにギリシア艦隊を難破させた》.</div>\r\n","<div class=\"hw\">Nauportum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ナウポルトゥム《Pannonia の町》.</div>\r\n","<div class=\"hw\">Nauportus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ナウポルトゥス《Nauportum 付近の川》.</div>\r\n","<div class=\"hw\">nausea, -ia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 船酔い.</div><div class=\"def\"><num>②</num> 吐き気, むかつき.</div><div class=\"def\"><num>③</num> 嫌悪.</div>\r\n","<div class=\"hw\">nauseola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[nausea]</div><div class=\"def\">(軽い)吐き気.</div>\r\n","<div class=\"hw\">nauseābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nauseo]</div><div class=\"def\"><num>①</num> 船酔いの.</div><div class=\"def\"><num>②</num> 吐き気を催す, むかつく.</div>\r\n","<div class=\"hw\">nauseātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://nauseō\">nauseō</a>]</div><div class=\"def\">船酔いしやすい人.</div>\r\n","<div class=\"hw\">nauseō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[nausea]</div><div class=\"def\"><num>①</num> 船酔いしている.</div><div class=\"def\"><num>②</num> 吐き気を催す, むかつく.</div><div class=\"def\"><num>③</num> 嫌悪する.</div>\r\n","<div class=\"hw\">nauseōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nausea]</div><div class=\"def\">吐き気を催させる.</div>\r\n","<div class=\"hw\">Nausicaā</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ナウシカアー《Phaeacia の王 Alcinous の娘;島に漂着した Ulixes に救いの手をさしのべた》.</div>\r\n","<div class=\"hw\">Nausiphanēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナウシパネース《Teos 出身のギリシアの哲学者;Epicurus の師》.</div>\r\n","<div class=\"hw\">nauta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船員, 水夫.</div>\r\n","<div class=\"hw\">nautea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 吐き気.</div><div class=\"def\"><num>②</num> (船底にたまる)汚水.</div>\r\n","<div class=\"hw\">nauticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 航海の, 海の, 船の</div><div class=\"ex\"><i>res nautica</i> (<author>C<small>AES</small></author>)<span class=\"ext\">海事, 航海.</span></div><div class=\"def\"><num>②</num> 船乗りの.</div>\r\n","<div class=\"hw\">nauticī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://nauticus\">nauticus</a>]</div><div class=\"def\">船員[水夫]たち.</div>\r\n","<div class=\"hw\">nautilus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙アオイガイ.</div>\r\n","<div class=\"hw\">Nautius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ナウティウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Nautiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ナウティイー《Minerva の祭をつかさどった一族》.</div>\r\n","<div class=\"hw\">nautālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nauta\">nauta</a>]</div><div class=\"def\">船員らしい.</div>\r\n","<div class=\"hw\">Navius<SUP>1</SUP></div><div class=\"pos\">-iī, <i>m</i></div><div class=\"def\">ナウィウス《ローマ人の氏族名;特に <i>Attus ～</i>, Tarquinius Priscus 王時代の有名な鳥占い師》.</div><hr><div class=\"hw\">Navius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Attus Navius の.</div>\r\n","<div class=\"hw\">Naxius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Naxos 島の.</div>\r\n","<div class=\"hw\">Naxos, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナクソス《Cyclades 諸島最大の島》.</div>\r\n","<div class=\"hw\">ne-</div><div class=\"pos\"><i>pref</i></div><div class=\"def\">否定を表わす:<i>nefas, nescio, neuter</i>, etc.</div>\r\n","<div class=\"hw\">Neaera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネアエラ, <SUP>*</SUP>ネアイラ《 (1) 前1世紀の詩人 Lygdamus(本名不詳)の恋人.(2) Horatius の恋人》.</div>\r\n","<div class=\"hw\">Nearchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネアルクス, <SUP>*</SUP>-コス《Alexander 大王の少年時代からの友;大王の東征に従い, Indus 川からペルシア湾までの航海記を著わした》.</div>\r\n","<div class=\"hw\">nebris</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bacchus の信徒たちが身にまとった小鹿の皮.</div>\r\n","<div class=\"hw\">nebula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 霧, かすみ, もや.</div><div class=\"def\"><num>②</num> ほこり, 煙.</div><div class=\"def\"><num>③</num> 雲.</div><div class=\"def\"><num>④</num> 薄膜.</div><div class=\"def\"><num>⑤</num> かげり, 闇.</div>\r\n","<div class=\"hw\">nebulō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://nebula\">nebula</a>]</div><div class=\"def\">ろくでなし, 役立たず.</div><hr><div class=\"hw\">nebulō<SUP>2</SUP></div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[nebula]</div><div class=\"def\">曇らせる, 暗くする.</div>\r\n","<div class=\"hw\">nebulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nebula]</div><div class=\"def\"><num>①</num> 霧[もや]の立ちこめた, 曇った.</div><div class=\"def\"><num>②</num> 蒸気[もや]のような.</div><div class=\"def\"><num>③</num> あいまいな, 不明瞭な.</div>\r\n","<div class=\"hw\">nec, neque</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"ori\">[ne-/-que<SUP>2</SUP>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>adv</i>)《古形》(通例 nec)...でない(=<a href=\"entry://nōn\">non</a>).</div><div class=\"def\"><num0>Ⅱ</num0> (<i>conj</i>)そして...でない;(単独で)そして...でさえない</div><div class=\"ex\"><i>neque unquam</i><span class=\"ext\">そして決して...でない</span></div><div class=\"ex\"><i>id, quod utile videbatur</i>, <i>neque erat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一見有益に見えて実はそうでなかったもの</span></div><div class=\"ex\"><i>neque vero</i><span class=\"ext\">そして実際...でない</span></div><div class=\"ex\"><i>neque enim</i><span class=\"ext\">というのも...でないから</span></div><div class=\"ex\"><i>neque tamen</i><span class=\"ext\">にもかかわらず...でない</span></div><div class=\"ex\"><i>neque...neque </i><span class=\"ext\">...でもなく...でもない</span></div><div class=\"ex\"><i>neque...et</i><span class=\"ext\">...でないばかりかむしろ...である</span></div><div class=\"ex\"><i>et...neque</i><span class=\"ext\">...であるばかりか...でない</span></div><div class=\"ex\"><i>nec non</i><span class=\"ext\">そして...も, そしてさらに.</span></div>\r\n","<div class=\"hw\">necdum</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"ori\">[nec/dum<SUP>2</SUP>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>conj</i>)そしてまだ...でない.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>adv</i>)まだ...でない.</div>\r\n","<div class=\"hw\">necesse</div><div class=\"pos\"><i>indecl adj n</i></div><div class=\"ori\">[ne-/cedo<SUP>2</SUP>]</div><div class=\"def\">必然の, 避けられない, やむをえない;必要な, 不可欠の</div><div class=\"ex\"><i>～ esse</i><span class=\"ext\">必然である, ...ねばならぬ 〈+<i>inf</i>;+<i>acc c. inf</i>;+<i>subj</i>;ut〉</span></div><div class=\"ex\">～ <i>habere</i> 〈+<i>inf</i>〉<span class=\"ext\">(...することを)必要と考える, ...ねばならぬ.</span></div>\r\n","<div class=\"hw\">necessitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://necesse\">necesse</a>]</div><div class=\"def\"><num>①</num> 必然性, 不可避.</div><div class=\"def\"><num>②</num> 必要, 不可欠.</div><div class=\"def\"><num>③</num> 強制, 圧迫.</div><div class=\"def\"><num>④</num> 難局, 苦境.</div><div class=\"def\"><num>⑤</num> 困窮, 窮乏.</div><div class=\"def\"><num>⑥</num> 必要なもの, 要求.</div><div class=\"def\"><num>⑦</num> やむをえない行為.</div><div class=\"def\"><num>⑧</num> (人と人との)きずな, 親しい関係(=<a href=\"entry://necessitūdō\">necessitudo</a>).</div>\r\n","<div class=\"hw\">necessitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[necesse]</div><div class=\"def\"><num>①</num> 必然性, 不可避.</div><div class=\"def\"><num>②</num> 強制, 拘束.</div><div class=\"def\"><num>③</num> 困窮, 窮乏.</div><div class=\"def\"><num>④</num> 必要なもの, 要求.</div><div class=\"def\"><num>⑤</num> (人と人との)きずな, 親しい関係.</div><div class=\"def\"><num>⑥</num> (<i>pl</i>)親戚, 友人.</div>\r\n","<div class=\"hw\">necessum, -us</div><div class=\"pos\"><i>indecl adj</i>《古形》</div><div class=\"def\">=<a href=\"entry://necesse\">necesse</a>.</div>\r\n","<div class=\"hw\">necessāria<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[necessarius<SUP>2</SUP>]</div><div class=\"def\">親戚, 友人《女性》.</div><hr><div class=\"hw\">necessāria<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[necessarius<SUP>1</SUP>]</div><div class=\"def\">生活必需品.</div>\r\n","<div class=\"hw\">necessārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[necesse]</div><div class=\"def\"><num>①</num> やむをえない, 避けられない, 必然の.</div><div class=\"def\"><num>②</num> 必要な, 不可欠の.</div><div class=\"def\"><num>③</num> 争う余地のない, 明白な.</div><div class=\"def\"><num>④</num> 緊急の, きわめて重大な.</div><div class=\"def\"><num>⑤</num> (血縁・友情・庇護関係などで)固く結ばれた.</div><hr><div class=\"hw\">necessārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">親戚, 友人.</div>\r\n","<div class=\"hw\">necessāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[necessarius<SUP>1</SUP>]</div><div class=\"def\">必然的に.</div>\r\n","<div class=\"hw\">necessāriō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://necessārius\">necessārius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> やむをえず, 余儀なく.</div><div class=\"def\"><num>②</num> 必然的に, 当然.</div>\r\n","<div class=\"hw\">necessō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[necesse]</div><div class=\"def\">不可欠にする.</div>\r\n","<div class=\"hw\">necne</div><div class=\"pos\"><i>conj</i>, <i>particle</i></div><div class=\"ori\">[nec/-ne]</div><div class=\"def\">...か否か, ...かどうか.</div>\r\n","<div class=\"hw\">necnōn</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">そして...も, そしてさらに.</div>\r\n","<div class=\"hw\">necopīnans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"ori\">[nec/opinor]</div><div class=\"def\">気づかない, 予期しない.</div>\r\n","<div class=\"hw\">necopīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://necopīnātus\">necopīnātus</a>]</div><div class=\"def\"><num>①</num> 思いがけない, 不測の.</div><div class=\"def\"><num>②</num> 気づかない, 予期しない.</div>\r\n","<div class=\"hw\">necopīnātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nec/opinor]</div><div class=\"def\">思いがけない, 不測の.</div>\r\n","<div class=\"hw\">necopīnātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://necopīnātus\">necopīnātus</a>]</div><div class=\"def\">思いがけなく, 突然.</div>\r\n","<div class=\"hw\">necrobiōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙類壊死<SUB>えし</SUB>.</div>\r\n","<div class=\"hw\">necrologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i>, <B>-um</B> -ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">死亡者名簿, 過去帳.</div>\r\n","<div class=\"hw\">necromantīa, -ēa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">降霊術.</div>\r\n","<div class=\"hw\">necropsia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙検死, 剖検.</div>\r\n","<div class=\"hw\">necroscopia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://necropsia\">necropsia</a>.</div>\r\n","<div class=\"hw\">necrōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙壊死<SUB>えし</SUB>, 壊疽<SUB>えそ</SUB>.</div>\r\n","<div class=\"hw\">Nectanabis, -tene-</div><div class=\"pos\">-idis, <B>Necthebis</B> -is, <i>m</i></div><div class=\"def\">ネクタナビス《エジプト王(前4世紀前半頃)》.</div>\r\n","<div class=\"hw\">nectar</div><div class=\"pos\">-aris, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙ネクタル, 神酒.</div><div class=\"def\"><num>②</num> 人間を不死にする[人間の姿を変える]飲料.</div><div class=\"def\"><num>③</num> 甘美なもの《特にぶどう酒・蜜・ミルクなど》.</div>\r\n","<div class=\"hw\">nectareus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nectar\">nectar</a>]</div><div class=\"def\"><num>①</num> 神酒を混ぜた.</div><div class=\"def\"><num>②</num> (神酒のように)甘美な.</div>\r\n","<div class=\"hw\">nectarius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://nectareus\">nectareus</a></div><div class=\"ex\"><i>herba nectaria</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">〘植〙オオグルマ.</span></div>\r\n","<div class=\"hw\">nectarītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オオグルマで芳香をつけたぶどう酒.</div>\r\n","<div class=\"hw\">nectō</div><div class=\"pos\">-ere nex(u)ī nexum, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> nassa, nodus]</div><div class=\"def\"><num>①</num> 織って[編んで]作る.</div><div class=\"def\"><num>②</num> 巻きつける, からませる.</div><div class=\"def\"><num>③</num> つなぎ合わせる, 結びつける;関連させる 〈alqd re〉.</div><div class=\"def\"><num>④</num> 拘束する.</div><div class=\"def\"><num>⑤</num> たくらむ, もくろむ.</div><div class=\"def\"><num>⑥</num> (詩文・演説などを)作る;物語る.</div>\r\n","<div class=\"hw\">necullus, nec ullus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">一つ[一人]もない.</div>\r\n","<div class=\"hw\">necātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[neco]</div><div class=\"def\">殺害者.</div>\r\n","<div class=\"hw\">necātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://necātor\">necātor</a>]</div><div class=\"def\">殺害者《女性》.</div>\r\n","<div class=\"hw\">necātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://necō\">neco</a>.</div>\r\n","<div class=\"hw\">necō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nex]</div><div class=\"def\"><num>①</num> 殺す.</div><div class=\"def\"><num>②</num> 滅ぼす, だいなしにする.</div><div class=\"def\"><num>③</num> 抑圧する.</div>\r\n","<div class=\"hw\">nefandus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ne-/for]</div><div class=\"def\">邪悪な, 憎むべき, 忌まわしい.</div>\r\n","<div class=\"hw\">nefans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"def\">=<a href=\"entry://nefandus\">nefandus</a>.</div>\r\n","<div class=\"hw\">nefastus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ne-/fastus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (神のおきてによって)禁じられている, 涜聖の, 不浄な</div><div class=\"ex\"><i>dies nefasti</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">(宗教上の理由から)公的業務の禁じられている日々.</span></div><div class=\"def\"><num>②</num> 忌まわしい, 恐ろしい.</div><div class=\"def\"><num>③</num> 不吉な, 縁起の悪い.</div>\r\n","<div class=\"hw\">nefārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nefārius\">nefārius</a>]</div><div class=\"def\">忌まわしい行為.</div>\r\n","<div class=\"hw\">nefārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nefās\">nefās</a>]</div><div class=\"def\"><num>①</num> 人倫に反した, 邪悪な.</div><div class=\"def\"><num>②</num> ひどい, 不快な.</div>\r\n","<div class=\"hw\">nefāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nefarius]</div><div class=\"def\">邪悪に, 非道に.</div>\r\n","<div class=\"hw\">nefās</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[ne-/fas]</div><div class=\"def\"><num>①</num> 不敬虔, 涜聖.</div><div class=\"def\"><num>②</num> 犯罪, 罪業</div><div class=\"ex\"><i>fas atque</i> ～ (<author>V<small>ERG</small></author>)<span class=\"ext\">正邪.</span></div><div class=\"def\"><num>③</num> 忌まわしいできごと, 恐ろしいもの.</div><div class=\"def\"><num>④</num> 邪悪な者, 悪人.</div><div class=\"def\"><num>⑤</num> 災難, 懲罰.</div>\r\n","<div class=\"hw\">negantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nego]</div><div class=\"def\">否定, 否認.</div>\r\n","<div class=\"hw\">negantinummius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nego/nummus]</div><div class=\"def\">お金を出そうとしない者.</div>\r\n","<div class=\"hw\">negitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[nego]</div><div class=\"def\">断固[繰り返して]否定[拒否]する.</div>\r\n","<div class=\"hw\">neglectiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[neglego]</div><div class=\"def\">無視, 軽視.</div>\r\n","<div class=\"hw\">neglectus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[neglego]</div><div class=\"def\"><num>①</num> 顧みられない, 無視[軽視]された.</div><div class=\"def\"><num>②</num> 不注意な.</div><hr><div class=\"hw\">neglectus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">無視, 軽視.</div>\r\n","<div class=\"hw\">neglegens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[neglego]</div><div class=\"def\"><num>①</num> 無頓着な, 不注意な 〈alcis rei;in re [alqd]〉.</div><div class=\"def\"><num>②</num> だらしのない, 雑然とした.</div><div class=\"def\"><num>③</num> 区別しない.</div>\r\n","<div class=\"hw\">neglegenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://neglegens\">neglegens</a>]</div><div class=\"def\">不注意に, ぞんざいに.</div>\r\n","<div class=\"hw\">neglegentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[neglegens]</div><div class=\"def\">怠慢, 不注意, 無頓着</div><div class=\"ex\"><i>epistularum</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">筆不精.</span></div>\r\n","<div class=\"hw\">neglegō</div><div class=\"pos\">-ere -lexī -lectum, <i>tr</i></div><div class=\"ori\">[nec/lego<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 無視する, 顧みない, 気にしない, 看過する 〈alqd;+<i>acc c. inf</i>;+間接疑問;de alqo〉</div><div class=\"ex\"><i>Aeduorum injurias non neglegere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Aedui 族に対する不正行為を見過ごさない.</span></div><div class=\"def\"><num>②</num> (...することを)怠る, ...しそこなう 〈+<i>inf</i>〉.</div><div class=\"def\"><num>③</num> 軽視する, 軽んずる</div><div class=\"ex\"><i>alcis imperium neglegere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">ある人の権威を軽んずる.</span></div><div class=\"def\"><num>④</num> 放棄[断念]する, なしですます.</div>\r\n","<div class=\"hw\">neglexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://neglegō\">neglego</a>.</div>\r\n","<div class=\"hw\">negātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nego]</div><div class=\"def\"><num>①</num> 否定, 否認;拒否, 拒絶.</div><div class=\"def\"><num>②</num> 〘文〙否定辞.</div>\r\n","<div class=\"hw\">negātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[nego]</div><div class=\"def\">否定者.</div>\r\n","<div class=\"hw\">negātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://negātor\">negātor</a>]</div><div class=\"def\">否定者《女性》.</div>\r\n","<div class=\"hw\">negātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://negō\">nego</a>.</div>\r\n","<div class=\"hw\">negātīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nego]</div><div class=\"def\"><num>①</num> 〘法〙禁止の.</div><div class=\"def\"><num>②</num> 〘文〙否定の.</div>\r\n","<div class=\"hw\">negātīvē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://negātīvus\">negātīvus</a>]</div><div class=\"def\">否定的に.</div>\r\n","<div class=\"hw\">negō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 否定[否認]する 〈alqd;+<i>acc c. inf</i>〉.</div><div class=\"def\"><num>②</num> 拒絶[拒否]する, 断わる 〈alqd;+<i>inf</i>〉.</div><div class=\"def\"><num>③</num> 禁ずる, 許さない 〈alci alqd;+<i>acc c. inf</i>〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)否と言う 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">negōtians</div><div class=\"pos\">-antis, <i>m</i>(<i>prp</i>)</div><div class=\"ori\">[negotior]</div><div class=\"def\">商人, (特に)卸売商人, 実業家.</div>\r\n","<div class=\"hw\">negōtiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[negotium]</div><div class=\"def\"><num>①</num> (小さな)仕事.</div><div class=\"def\"><num>②</num> (ちょっとした)問題.</div>\r\n","<div class=\"hw\">negōtior</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"ori\">[negotium]</div><div class=\"def\">商売[取引]をする.</div>\r\n","<div class=\"hw\">negōtium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[nec/otium]</div><div class=\"def\"><num>①</num> 仕事, 活動.</div><div class=\"def\"><num>②</num> 苦労, 骨折り</div><div class=\"ex\"><i>sine negotio</i> (<author>N<small>EP</small></author>)<span class=\"ext\">苦もなく.</span></div><div class=\"def\"><num>③</num> 迷惑, 面倒</div><div class=\"ex\">～ <i>alci facessere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に迷惑をかける.</span></div><div class=\"def\"><num>④</num> (なすべき)仕事, 務め</div><div class=\"ex\"><i>dare</i> ～ <i>alci</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に任務を与える.</span></div><div class=\"def\"><num>⑤</num> 国政, 公務.</div><div class=\"def\"><num>⑥</num> (個人に)関すること, 利益</div><div class=\"ex\"><i>suum ～ agere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自分のことだけをする.</span></div><div class=\"def\"><num>⑦</num> 商売, 取引.</div><div class=\"def\"><num>⑧</num> 訴訟.</div><div class=\"def\"><num>⑨</num> 問題, 事態</div><div class=\"ex\"><i>quid negotii est?</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">何が問題なのか, どうしたのか.</span></div><div class=\"def\"><num>⑩</num> こと, 事柄;人, やつ.</div>\r\n","<div class=\"hw\">negōtiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[negotium]</div><div class=\"def\">仕事に関する, 業務上の.</div>\r\n","<div class=\"hw\">negōtiātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[negotior]</div><div class=\"def\">商売, 取引.</div>\r\n","<div class=\"hw\">negōtiātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[negotior]</div><div class=\"def\">商人, (特に)卸売商人.</div>\r\n","<div class=\"hw\">negōtiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://negōtium\">negōtium</a>]</div><div class=\"def\"><num>①</num> 仕事の多い, 多忙な.</div><div class=\"def\"><num>②</num> 骨の折れる, 厄介な.</div><div class=\"def\"><num>③</num> 仕事の</div><div class=\"ex\"><i>negotiosi dies</i> (<author>T<small>AC</small></author>)<span class=\"ext\">仕事をする日々.</span></div>\r\n","<div class=\"hw\">Nemausum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ネマウスム《Gallia Narbonensis の町;現 Nîmes》.</div>\r\n","<div class=\"hw\">Nemea<SUP>1</SUP></div><div class=\"pos\">-ae, <B>Nemeē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネメア《Argolis の谷;Hercules がライオンを退治した場所》.</div><hr><div class=\"hw\">Nemea<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネメア祭《2年ごとに Nemea で催されたギリシアの四大競技祭の一つ》.</div>\r\n","<div class=\"hw\">Nemeaeus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Nemea<SUP>1</SUP> の.</div><div class=\"def\"><num>②</num> Nemea のライオンの.</div><hr><div class=\"hw\">Nemeaeus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘天・占星〙獅子座(=<a href=\"entry://leō\">Leo</a>).</div>\r\n","<div class=\"hw\">Nemesis</div><div class=\"pos\">-is [-eōs], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ネメシス《人間の傲慢を罰する女神》.</div>\r\n","<div class=\"hw\">Nemetocenna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ネメトケンナ《Gallia Belgica にあった, Atrebates 族の町;現 Arras》.</div>\r\n","<div class=\"hw\">Nemetēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ネメテース《Gallia Belgica にいたゲルマン系一部族》.</div>\r\n","<div class=\"hw\">nemorensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nemus]</div><div class=\"def\">森の;(特に, Aricia 付近にあった)Diana の聖林の.</div>\r\n","<div class=\"hw\">nemorivagus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nemus/vagus<SUP>1</SUP>]</div><div class=\"def\">森をうろつく.</div>\r\n","<div class=\"hw\">nemorālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nemus]</div><div class=\"def\">森の, 森林の</div><div class=\"ex\"><i>templum nemorale Dianae</i> (<author>O<small>V</small></author>)<span class=\"ext\">(Aricia 付近にあった)Diana の森深い神殿.</span></div>\r\n","<div class=\"hw\">nemorōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nemus]</div><div class=\"def\"><num>①</num> 森の多い.</div><div class=\"def\"><num>②</num> 葉の茂った.</div>\r\n","<div class=\"hw\">nempe</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"ori\">[<i>cf</i>. nam, quippe]</div><div class=\"def\">本当に, 確かに;もちろん.</div>\r\n","<div class=\"hw\">nemus</div><div class=\"pos\">nemoris, <i>n</i></div><div class=\"def\"><num>①</num> 森, 森林.</div><div class=\"def\"><num>②</num> 植樹;樹木.</div><div class=\"def\"><num>③</num> 聖林, 神にささげられた森;(特に)Diana にささげられた Aricia の森.</div>\r\n","<div class=\"hw\">Neobūlē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネオブーレー《Horatius の詩に登場する娘の名》.</div>\r\n","<div class=\"hw\">Neoclēs</div><div class=\"pos\">-is [-ī], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネオクレース《Themistocles の父》.</div>\r\n","<div class=\"hw\">Neoclīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Neocles の息子(=<a href=\"entry://Themistoclēs\">Themistocles</a>).</div>\r\n","<div class=\"hw\">neomēnia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">新月.</div>\r\n","<div class=\"hw\">Neontīchos</div><div class=\"pos\">(用例は <i>nom</i>, <i>acc</i> のみ), <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネオンティーコス, <SUP>*</SUP>-テイ-《Thracia の要塞》.</div>\r\n","<div class=\"hw\">neonātus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘医〙新生児.</div>\r\n","<div class=\"hw\">neophytus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">新しくキリスト教に改宗した人.</div>\r\n","<div class=\"hw\">neoplasma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘病〙新生物.</div>\r\n","<div class=\"hw\">Neoptolemus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ネオプトレムス, <SUP>*</SUP>-モス《Achilles の息子;Troja 戦争で Priamus を殺した;Pyrrhus とも呼ばれた》.</div>\r\n","<div class=\"hw\">nepa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘動〙サソリ.</div><div class=\"def\"><num>②</num> (N-)〘天〙サソリ座.</div>\r\n","<div class=\"hw\">Nepesīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nepete の.</div>\r\n","<div class=\"hw\">nepeta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙シソ科カラミンタ属の植物.</div>\r\n","<div class=\"hw\">Nepete</div><div class=\"pos\">-is, <i>n</i>, <B>-a</B> -ae, <i>f</i></div><div class=\"def\">ネペテ《Etruria 南部の町;現 Nepi》.</div>\r\n","<div class=\"hw\">Nephelaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nephele の.</div>\r\n","<div class=\"hw\">Nephelē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ネペレー《Athamas の妻で Phrixus と Helle の母》.</div>\r\n","<div class=\"hw\">Nephelēias</div><div class=\"pos\">-adis [-ados], <i>f</i></div><div class=\"def\">=<a href=\"entry://Nephelēis\">Nepheleis</a>.</div>\r\n","<div class=\"hw\">Nephelēis</div><div class=\"pos\">-idos [-idis], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Nephele の娘(=<a href=\"entry://Hellē\">Helle</a>).</div>\r\n","<div class=\"hw\">nephralgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙腎臓痛.</div>\r\n","<div class=\"hw\">nephrectomia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙腎摘出(術).</div>\r\n","<div class=\"hw\">nephridium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙腎管.</div>\r\n","<div class=\"hw\">nephrocirrhōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙腎硬変(症).</div>\r\n","<div class=\"hw\">nephrolithiasis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙腎石症.</div>\r\n","<div class=\"hw\">nephropathīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙腎症.</div>\r\n","<div class=\"hw\">nephropyelītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙腎盂<SUB>じんう</SUB>腎炎.</div>\r\n","<div class=\"hw\">nephrītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙腎炎.</div>\r\n","<div class=\"hw\">nephrōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙ネフローゼ.</div>\r\n","<div class=\"hw\">neptis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>cf. </i> nepos]</div><div class=\"def\"><num>①</num> 孫娘.</div><div class=\"def\"><num>②</num> 女系子孫.</div>\r\n","<div class=\"hw\">Neptūnicola</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[Neptunus/colo<SUP>2</SUP>]</div><div class=\"def\">Neptunus の崇拝者.</div>\r\n","<div class=\"hw\">Neptūnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》Neptunus の</div><div class=\"ex\"><i>arva [loca] Neptunia</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Neptunus の野原(=海)</span></div><div class=\"ex\">～ <i>dux</i> (<author>H<small>OR</small></author>)<span class=\"ext\">=Sextus Pompeius《自らを Neptunus の養子と称した》.</span></div>\r\n","<div class=\"hw\">Neptūnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 〘神話〙ネプトゥーヌス《海神;Juppiter の兄弟で Amphitrite の夫;ギリシア神話の Poseidon に当たる》.</div><div class=\"def\"><num>②</num> 《詩》海.</div>\r\n","<div class=\"hw\">Neptūnālia</div><div class=\"pos\">-ium [-iōrum], <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Neptūnālis\">Neptūnālis</a>]</div><div class=\"def\">Neptunus の祭典《7月23日に行なわれた》.</div>\r\n","<div class=\"hw\">Neptūnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Neptunus の.</div>\r\n","<div class=\"hw\">nepōs</div><div class=\"pos\">-ōtis, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 孫.</div><div class=\"def\"><num>②</num> 子孫.</div><div class=\"def\"><num>③</num> 甥<SUB>おい</SUB>.</div><div class=\"def\"><num>④</num> 道楽者, 浪費家.</div>\r\n","<div class=\"hw\">Nepōs</div><div class=\"pos\">-ōtis, <i>m</i></div><div class=\"def\">ネポース《Cornelia 氏族に属する家名;特に <i>Cornelius ～</i>, 伝記作家で Cicero の友人(前99?‐?24)》.</div>\r\n","<div class=\"hw\">nepōtor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[nepos]</div><div class=\"def\">浪費する.</div>\r\n","<div class=\"hw\">nepōtula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nepōtulus\">nepōtulus</a>]</div><div class=\"def\">《碑》(小さな)孫娘.</div>\r\n","<div class=\"hw\">nepōtulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[nepos]</div><div class=\"def\">(小さな)孫.</div>\r\n","<div class=\"hw\">nepōtālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nepos]</div><div class=\"def\">浪費家の.</div>\r\n","<div class=\"hw\">nepōtātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://nepōtor\">nepōtor</a>]</div><div class=\"def\">浪費.</div>\r\n","<div class=\"hw\">neque</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"def\">=<a href=\"entry://nec\">nec</a>.</div>\r\n","<div class=\"hw\">nequedum</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"def\">=<a href=\"entry://necdum\">necdum</a>.</div>\r\n","<div class=\"hw\">nequeō</div><div class=\"pos\">-quīre -quīvī [-quiī] -quitum, <i>intr</i></div><div class=\"def\">...できない, ...する能力がない 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">nequitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nequeō\">nequeo</a>.</div>\r\n","<div class=\"hw\">nequiī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://nequīvī\">nequivi</a>(⇒ <a href=\"entry://nequeō\">nequeo</a>).</div>\r\n","<div class=\"hw\">nequīre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://nequeō\">nequeo</a>.</div>\r\n","<div class=\"hw\">nequīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nequeō\">nequeo</a>.</div>\r\n","<div class=\"hw\">Nerius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ネリウス《Horatius 時代の有名な高利貸し》.</div>\r\n","<div class=\"hw\">Nersae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ネルサエ《Latium にあった Aequi 族の町》.</div>\r\n","<div class=\"hw\">Nerthus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">ネルトゥス《ゲルマン人の豊穣の女神》.</div>\r\n","<div class=\"hw\">Nerulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ネルルム《Lucania 南部の町》.</div>\r\n","<div class=\"hw\">Nerva</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ネルウァ《ローマ人の家名;特に <i>M. Cocceius ～</i>, ローマ皇帝(在位96‐98);五腎帝の最初の皇帝》.</div>\r\n","<div class=\"hw\">nervia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>cf. </i> nervus]</div><div class=\"def\">〘解〙腱<SUB>けん</SUB>.</div>\r\n","<div class=\"hw\">nerviae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>cf. </i> nervus]</div><div class=\"def\"><num>①</num> (楽器の)弦.</div><div class=\"def\"><num>②</num> (測量師の)おもりをつるす糸.</div>\r\n","<div class=\"hw\">Nervicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nervii 族の.</div>\r\n","<div class=\"hw\">Nerviī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ネルウィイー《Gallia Belgica にいた一部族;Caesar に征服された》.</div>\r\n","<div class=\"hw\">nervulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nervus\">nervus</a>]</div><div class=\"def\">(<i>pl</i>)活力, 精力.</div>\r\n","<div class=\"hw\">nervus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 腱<SUB>けん</SUB>, 筋.</div><div class=\"def\"><num>②</num> (楽器の)弦;(<i>pl</i>)弦楽器.</div><div class=\"def\"><num>③</num> 弓のつる.</div><div class=\"def\"><num>④</num> (盾をおおう)革.</div><div class=\"def\"><num>⑤</num> (囚人の)足かせ.</div><div class=\"def\"><num>⑥</num> 力, 精力, 活力.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘解〙神経</div><div class=\"ex\">～ <i>vagus</i><span class=\"ext\">迷走神経.</span></div>\r\n","<div class=\"hw\">nervōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nervōsus\">nervōsus</a>]</div><div class=\"def\">(繊維などの)頑丈[丈夫]なこと.</div>\r\n","<div class=\"hw\">nervōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nervus]</div><div class=\"def\"><num>①</num> 筋肉の多い, 筋骨たくましい.</div><div class=\"def\"><num>②</num> (文体が)力強い, 勢いのある.</div>\r\n","<div class=\"hw\">nervōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nervosus]</div><div class=\"def\">強く, 勢いよく.</div>\r\n","<div class=\"hw\">Nerātius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ネラーティウス《ローマ人の氏族名;特に <i>L</i>. <i>～ Priscus</i>, Trajanus 帝時代の高名な法学者》.</div>\r\n","<div class=\"hw\">Nerētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ネレートゥム《Calabria の町》.</div>\r\n","<div class=\"hw\">Nerō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ネロー《Claudia 氏族に属する家名;特に (1) <i>C. Claudius ～</i>, 執政官(前207)として Metaurus 河畔の戦いで, Hasdrubal を破った.(2) ～ <i>Claudius Caesar</i>, ローマ第5代皇帝(在位54‐68);暴君として知られる》.</div>\r\n","<div class=\"hw\">Nerōnia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">ネロ祭《Nero 帝が創始した競技祭》.</div>\r\n","<div class=\"hw\">Nerōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Nerōnēus\">Neroneus</a>.</div>\r\n","<div class=\"hw\">Nerōnēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nero 帝の</div><div class=\"ex\"><i>mensis ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">Nero の月《Nero 帝時代に Aprilis(4月)をこう呼んだ》.</span></div>\r\n","<div class=\"hw\">Nesactium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ネサクティウム《Histria の町》.</div>\r\n","<div class=\"hw\">nesciens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://nesciō\">nesciō</a>]</div><div class=\"def\">知らない, 気づかない 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">nescius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nesciō\">nesciō</a>]</div><div class=\"def\"><num>①</num> 知らない, 気づかない 〈+<i>gen</i>;+<i>acc c. inf</i>〉.</div><div class=\"def\"><num>②</num> 経験のない 〈+<i>gen</i>〉.</div><div class=\"def\"><num>③</num> (...することが)できない 〈+<i>inf</i>〉.</div><div class=\"def\"><num>④</num> 知られていない.</div>\r\n","<div class=\"hw\">nesciō</div><div class=\"pos\">-īre -scīvī [-sciī] -scītum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[ne-/scio]</div><div class=\"def\"><num>①</num> 知らない, 気づかない 〈alqd;+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>～ an</i><span class=\"ext\">おそらくは</span></div><div class=\"ex\"><i>～ quis</i><span class=\"ext\">誰か(ある人)が</span></div><div class=\"ex\"><i>～ quo modo [pacto]</i><span class=\"ext\">何らかの方法で, どうにかこうにか.</span></div><div class=\"def\"><num>②</num> (...することが)できない 〈alqd;+<i>inf</i>〉</div><div class=\"ex\"><i>nescire Graece</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ギリシア語ができない.</span></div>\r\n","<div class=\"hw\">Nessus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネッスス, <SUP>*</SUP>-ソス《 (1) 〘伝説〙Centaurus 族の一人;Hercules の妻 Deianira に暴行しようとして Hercules に毒矢で殺された.(2) Thracia の川》.</div>\r\n","<div class=\"hw\">Nessēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nessus (1) の.</div>\r\n","<div class=\"hw\">Nestōr</div><div class=\"pos\">-oris, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ネストール《Neleus の息子;Pylus の王;Troja 戦争では賢い老王としてギリシア軍の御意見番をつとめた》.</div>\r\n","<div class=\"hw\">neu</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">=<a href=\"entry://nēve\">neve</a>.</div>\r\n","<div class=\"hw\">neuma</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘音〙ネウマ《中世の単旋聖歌の高低・律動などを表示した記号》.</div><div class=\"def\"><num>②</num> (<i>pl</i>)旋律, 調べ.</div>\r\n","<div class=\"hw\">neuralgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙神経痛</div><div class=\"ex\"><i>～ trigeminalis</i><span class=\"ext\">三叉神経痛.</span></div>\r\n","<div class=\"hw\">neurasthenia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙神経衰弱(症).</div>\r\n","<div class=\"hw\">neurilemma</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘解〙神経線維鞘<SUB>しょう</SUB>.</div>\r\n","<div class=\"hw\">neuroglia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘解〙神経支持質, 神経膠.</div>\r\n","<div class=\"hw\">neurohumor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘生理〙神経(体)液.</div>\r\n","<div class=\"hw\">neurologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙神経学.</div>\r\n","<div class=\"hw\">neuron</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙神経単位.</div>\r\n","<div class=\"hw\">neuroparalysis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙神経麻痺.</div>\r\n","<div class=\"hw\">neuropathīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙神経障害.</div>\r\n","<div class=\"hw\">neuropodium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙神経足, 腹肢.</div>\r\n","<div class=\"hw\">neurotomia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙</div><div class=\"def\"><num>①</num> 神経切断(術).</div><div class=\"def\"><num>②</num> 神経解剖学.</div>\r\n","<div class=\"hw\">neurītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙神経炎</div><div class=\"ex\"><i>～ multiplex</i><span class=\"ext\">多発性神経炎(=<a href=\"entry://polyneurītis\">polyneuritis</a>)</span></div><div class=\"ex\"><i>～ endemica</i><span class=\"ext\">地方病性神経炎(=脚気)</span></div><div class=\"ex\"><i>～ optica</i><span class=\"ext\">視神経炎</span></div><div class=\"ex\"><i>～ toxica</i><span class=\"ext\">中毒性神経炎.</span></div>\r\n","<div class=\"hw\">neurōma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘病〙神経腫.</div>\r\n","<div class=\"hw\">neurōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙神経症, ノイローゼ.</div>\r\n","<div class=\"hw\">neuter</div><div class=\"pos\">-tra -trum(<i>gen</i> neutrīus), <i>adj</i></div><div class=\"ori\">[ne-/uter<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> どちらも...でない.</div><div class=\"def\"><num>②</num> 中立の.</div><div class=\"def\"><num>③</num> 〘文〙中性の.</div>\r\n","<div class=\"hw\">neutiquam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ne-/ut/quam]</div><div class=\"def\">決して...ない.</div>\r\n","<div class=\"hw\">neutrub<img class=\"font\" src=\"img/A130.png\"></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[neuter/ubi]</div><div class=\"def\">どちらの場所にも...ない.</div>\r\n","<div class=\"hw\">neutrālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[neuter]</div><div class=\"def\">〘文〙中性の.</div>\r\n","<div class=\"hw\">neutrō</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[neuter]</div><div class=\"def\">どちらの側[方向]でも...ない.</div>\r\n","<div class=\"hw\">nex</div><div class=\"pos\">necis, <i>f</i></div><div class=\"ori\">[<i>cf</i>. noceo, noxa]</div><div class=\"def\"><num>①</num> 殺害, 殺すこと.</div><div class=\"def\"><num>②</num> (一般に)死.</div><div class=\"def\"><num>③</num> 殺された者の血.</div>\r\n","<div class=\"hw\">nexilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[necto]</div><div class=\"def\">つなぎ[結び]合わされた.</div>\r\n","<div class=\"hw\">nexum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[necto]</div><div class=\"def\">身体拘束《債務不履行の場合に債務者が債権者の奴隷になること》.</div>\r\n","<div class=\"hw\">nexus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[necto]</div><div class=\"def\">担保[抵当]に入れられた.</div><hr><div class=\"hw\">nexus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(債務不履行による)奴隷.</div><hr><div class=\"hw\">nexus<SUP>3</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 結合, からみ合うこと.</div><div class=\"def\"><num>②</num> 結び目, 継手;きずな, 結びつき.</div><div class=\"def\"><num>③</num> =<a href=\"entry://nexum\">nexum</a>.</div><div class=\"def\"><num>④</num> 組み合わせたもの, からみ合ったもの.</div>\r\n","<div class=\"hw\">nexuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nectō\">necto</a>, <a href=\"entry://nexō\">nexo</a>.</div>\r\n","<div class=\"hw\">nexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://nexuī\">nexui</a>.</div>\r\n","<div class=\"hw\">nexō</div><div class=\"pos\">-ere -xuī [-xī], <i>tr freq</i></div><div class=\"ori\">[necto]</div><div class=\"def\">結び合わせる, からみ合わせる.</div>\r\n","<div class=\"hw\">Neāpolis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネアーポリス《いくつかのギリシアの町の名;特に Campania の町(もともとギリシア人の植民市);現 Napoli》.</div>\r\n","<div class=\"hw\">Neāpolītis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Neapolis の.</div>\r\n","<div class=\"hw\">Neāpolītānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">Neapolis 付近の Pompeius の別荘.</div>\r\n","<div class=\"hw\">Neāpolītānus</div><div class=\"pos\">-a -um</div><div class=\"def\">Neapolis の.</div><div class=\"hw2\"><b>Neāpolītānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Neapolis の住民.</div>\r\n","<div class=\"hw\">Neāpolītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Neapolis 人.</div>\r\n","<div class=\"hw\">neō</div><div class=\"pos\">-ēre nēvī nētum, <i>tr</i></div><div class=\"def\"><num>①</num> 紡ぐ.</div><div class=\"def\"><num>②</num> 織る.</div>\r\n","<div class=\"hw\">neōtericus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">当今の, 近ごろの.</div>\r\n","<div class=\"hw\">neōtericī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://neōtericus\">neōtericus</a>]</div><div class=\"def\">当今の作家.</div>\r\n","<div class=\"hw\">nictor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://nictō\">nicto</a>.</div>\r\n","<div class=\"hw\">nictus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[nicto]</div><div class=\"def\">まばたき, 目くばせ.</div>\r\n","<div class=\"hw\">nictātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nictō\">nictō</a>]</div><div class=\"def\">まばたき.</div>\r\n","<div class=\"hw\">nictō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[<i>cf</i>. coniveo]</div><div class=\"def\"><num>①</num> まばたきする.</div><div class=\"def\"><num>②</num> ちらちら光る, またたく.</div><div class=\"def\"><num>③</num> 目くばせする.</div>\r\n","<div class=\"hw\">nigellus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://niger\">niger</a>]</div><div class=\"def\">黒みがかった, 黒っぽい.</div>\r\n","<div class=\"hw\">niger</div><div class=\"pos\">-gra -grum, <i>adj</i></div><div class=\"def\"><num>①</num> 黒い, 暗色の.</div><div class=\"def\"><num>②</num> 肌の黒い, 浅黒い;黒髪の.</div><div class=\"def\"><num>③</num> 暗い;暗黒の.</div><div class=\"def\"><num>④</num> 死の, 陰鬱な;不吉な.</div><div class=\"def\"><num>⑤</num> 邪悪な, よこしまな.</div>\r\n","<div class=\"hw\">Nigidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ニギディウス《ローマ人の氏族名;特に <i>P. ～ Figulus</i>, Cicero や Caesar と同時代の卓越した学者》.</div>\r\n","<div class=\"hw\">nigrans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[nigro]</div><div class=\"def\">黒い;暗い.</div>\r\n","<div class=\"hw\">nigrescō</div><div class=\"pos\">-ere -gruī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://nigreō\">nigreō</a>]</div><div class=\"def\">黒くなる;暗くなる.</div>\r\n","<div class=\"hw\">nigreō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[niger]</div><div class=\"def\">暗くなる.</div>\r\n","<div class=\"hw\">nigricans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://nigricō\">nigricō</a>]</div><div class=\"def\"><num>①</num> 黒みがかった, 黒っぽい.</div><div class=\"def\"><num>②</num> 光のない, 暗い, はっきりしない.</div>\r\n","<div class=\"hw\">nigricō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[niger]</div><div class=\"def\">黒ずむ.</div>\r\n","<div class=\"hw\">Nigris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニグリス《Aethiopia の大河;おそらく現 Niger》.</div>\r\n","<div class=\"hw\">nigritia</div><div class=\"pos\">-ae, <B>-ēs</B> -ēī, <i>f</i></div><div class=\"ori\">[niger]</div><div class=\"def\">黒色.</div>\r\n","<div class=\"hw\">nigritūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">=<a href=\"entry://nigritia\">nigritia</a>.</div>\r\n","<div class=\"hw\">nigror</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[niger]</div><div class=\"def\">黒色, 黒さ.</div>\r\n","<div class=\"hw\">nigrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[niger]</div><div class=\"def\">黒い点</div><div class=\"ex\">～ <i>oculi</i> (<author>C<small>ELS</small></author>)<span class=\"ext\">目の黒い点(=ひとみ).</span></div>\r\n","<div class=\"hw\">nigruī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nigrescō\">nigresco</a>.</div>\r\n","<div class=\"hw\">nigrēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[niger]</div><div class=\"def\">黒色, 黒さ.</div>\r\n","<div class=\"hw\">Nigrītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニグリータエ, <SUP>*</SUP>-タイ《Nigris 河畔にいた一部族》.</div>\r\n","<div class=\"hw\">nigrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[niger]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)黒い.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)黒くする.</div>\r\n","<div class=\"hw\">nihil<SUP>1</SUP>, nīl<SUP>1</SUP></div><div class=\"pos\"><i>indecl n</i>(<i>gen</i> nullīus reī)</div><div class=\"ori\">[<i>cf. </i> nihilum]</div><div class=\"def\"><num>①</num> 無, (何も)ないこと</div><div class=\"ex\"><i>non ～</i><span class=\"ext\">多少</span></div><div class=\"ex\"><i>～ non</i><span class=\"ext\">すべて, 何でも</span></div><div class=\"ex\"><i>～ aliud nisi [quam]</i><span class=\"ext\">ただ...だけ, ...にすぎない, ...にほかならない</span></div><div class=\"ex\">～ <i>minus</i><span class=\"ext\">決して[全く]...(で)ない.</span></div><div class=\"def\"><num>②</num> 無意味, 無価値</div><div class=\"ex\">～ <i>esse</i><span class=\"ext\">無価値である, 役に立たぬ.</span></div><hr><div class=\"hw\">nihil<SUP>2</SUP>, nīl<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 全く[決して]...ない</div><div class=\"ex\"><i>non</i> ～<span class=\"ext\">かなり, 少なからず.</span></div><div class=\"def\"><num>②</num> 何の理由もなく.</div>\r\n","<div class=\"hw\">nihildum</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://nihil\">nihil<SUP>2</SUP>, nīl<SUP>2</SUP></a>/dum<SUP>2</SUP>]</div><div class=\"def\">まだ何も...ない.</div>\r\n","<div class=\"hw\">nihilum<SUP>1</SUP>, nīlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ne-/hilum]</div><div class=\"def\">無, (何も)ないこと</div><div class=\"ex\"><i>ad ～ venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">無に帰する</span></div><div class=\"ex\"><i>nihili</i>(価値を表わす <i>gen</i>)<i>facere</i> (<author>C<small>IC</small></author>) =<i>pro nihilo putare [ducere]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">無価値[取るに足らぬもの]とみなす</span></div><div class=\"ex\"><i>de nihilo</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">むなしく, いたずらに, 根拠なく</span></div><div class=\"ex\"><i>nihilo</i> 〈+<i>comp</i>〉<span class=\"ext\">少しも...でない</span></div><div class=\"ex\"><i>nihilo beatior</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(...より)少しも幸せでない.</span></div><hr><div class=\"hw\">nihilum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://nihil\">nihil<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">nihilōminus, nihilō minus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nihilum\">nihilum<SUP>1</SUP>, nīlum</a>]</div><div class=\"def\">それにもかかわらず, それでもやはり.</div>\r\n","<div class=\"hw\">nimbifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[nimbus/fero]</div><div class=\"def\">あらしをもたらす.</div>\r\n","<div class=\"hw\">nimbus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 雨雲.</div><div class=\"def\"><num>②</num> (一面の)煙, 砂塵.</div><div class=\"def\"><num>③</num> 大群.</div><div class=\"def\"><num>④</num> 土砂降り, 豪雨, あらし.</div><div class=\"def\"><num>⑤</num> 流出, 噴出.</div><div class=\"def\"><num>⑥</num> (雨あられと)降り注ぐこと.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>(聖像の)後光, 光輪.</div>\r\n","<div class=\"hw\">nimbātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nimbus]</div><div class=\"def\">猛烈な, 激しい.</div>\r\n","<div class=\"hw\">nimbōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nimbus\">nimbus</a>]</div><div class=\"def\">雨雲におおわれた;あらしをもたらす, あらしの.</div>\r\n","<div class=\"hw\">nimietās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[nimius]</div><div class=\"def\">過多, 過剰.</div>\r\n","<div class=\"hw\">nimiopere, nimiō opere</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[nimium<SUP>1</SUP>/opus]</div><div class=\"def\">過度に.</div>\r\n","<div class=\"hw\">nimis</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 過度に, あまりに.</div><div class=\"def\"><num>②</num> 非常に, 大いに</div><div class=\"ex\"><i>non ～</i><span class=\"ext\">大して...ない.</span></div>\r\n","<div class=\"hw\">nimium<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[nimius]</div><div class=\"def\"><num>①</num> 過度, 過多.</div><div class=\"def\"><num>②</num> 大量, 豊富.</div><hr><div class=\"hw\">nimium<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://nimis\">nimis</a>.</div>\r\n","<div class=\"hw\">nimius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nimis]</div><div class=\"def\"><num>①</num> 過度の, 極端な, 過剰な.</div><div class=\"def\"><num>②</num> 中庸を欠いた, 節度のない.</div><div class=\"def\"><num>③</num> 非常な.</div>\r\n","<div class=\"hw\">nimiō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[nimium<SUP>1</SUP>]</div><div class=\"def\">並はずれて, はるかに.</div>\r\n","<div class=\"hw\">ninguis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://nix\">nix</a>.</div>\r\n","<div class=\"hw\">ning(u)it</div><div class=\"pos\">-ere ninxit, <i>intr impers</i></div><div class=\"ori\">[<i>cf. </i> nix, nivit]</div><div class=\"def\">雪が降る.</div>\r\n","<div class=\"hw\">Ninivē, -ne-</div><div class=\"pos\">-ēs, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ニニウェー, <SUP>∥</SUP>ニネヴェ《Assyria の首都(⇒ <a href=\"entry://Ninus\">Ninus (2)</a> )》.</div>\r\n","<div class=\"hw\">Ninnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ニンニウス《Campania の貴族の氏族名;特に (1) <i>L. ～ Quadratus</i>, 護民官(前58).(2) <i>～ Crassus</i>, Homerus の <i>Ilias</i> をラテン語に訳した(前1世紀?)》.</div>\r\n","<div class=\"hw\">Ninus, -os</div><div class=\"pos\">-ī, <i>m</i>, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニヌス, <SUP>*</SUP>-ノス《 (1)(<i>m</i>)〘伝説〙Assyria 初代の王で Semiramis の夫;Ninus の伝説上の建設者.(2)(<i>f</i>)Assyria の首都 Ninive の古名》.</div>\r\n","<div class=\"hw\">ninxit</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://ning(u)it\">ninguit</a>.</div>\r\n","<div class=\"hw\">Niobidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Niobe の子供たち.</div>\r\n","<div class=\"hw\">Niobē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニオベー《Tantalus の娘で Amphion の妻;Latona に自分の子供の数を自慢したため, 14人の子供全部を Latona の子 Apollo と Diana によって射殺された;彼女は悲嘆のあまり石と化したが, 涙を流し続けたという》.</div>\r\n","<div class=\"hw\">Niobēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Niobe の.</div>\r\n","<div class=\"hw\">Niphātēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニパーテース《Armenia の Taurus 山脈の山》.</div>\r\n","<div class=\"hw\">Niptra</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">「足洗い」《Sophocles と Pacuvius の劇の題名》.</div>\r\n","<div class=\"hw\">nisi</div><div class=\"pos\"><i>conj</i></div><div class=\"ori\">[ne-/si]</div><div class=\"def\"><num>①</num> (もし)...でなければ.</div><div class=\"def\"><num>②</num> (否定辞のあとに)...を除いては, ...のほかは</div><div class=\"ex\"><i>nihil aliud ～</i><span class=\"ext\">ほかならぬ(この)..., ...以外の何ものでもない</span></div><div class=\"ex\"><i>non</i> ～<span class=\"ext\">単に, ただ</span></div><div class=\"ex\"><i>～ si</i><span class=\"ext\">...でなければ</span></div><div class=\"ex\"><i>～ quod</i><span class=\"ext\">...であることを除いては, ...であるほかは</span></div><div class=\"ex\"><i>～ forte [vero]</i> 〈+<i>ind</i>〉<span class=\"ext\">ひょっとして...でないならば.</span></div>\r\n","<div class=\"hw\">Nisibis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニシビス《Mesopotamia の町》.</div>\r\n","<div class=\"hw\">nitens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://niteō\">niteō</a>]</div><div class=\"def\"><num>①</num> 輝く, 光る.</div><div class=\"def\"><num>②</num> (動物などが)手入れのよい, つやつやした.</div><div class=\"def\"><num>③</num> (文体が)洗練された, 優雅な.</div><div class=\"def\"><num>④</num> 輝かしい, 際立った.</div>\r\n","<div class=\"hw\">nitescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://niteō\">niteō</a>]</div><div class=\"def\"><num>①</num> 光り[輝き]だす.</div><div class=\"def\"><num>②</num> 栄養がよくなる, つやつやする.</div>\r\n","<div class=\"hw\">niteō</div><div class=\"pos\">-ēre -tuī, <i>intr</i></div><div class=\"def\"><num>①</num> 光る, 輝く.</div><div class=\"def\"><num>②</num> 栄養がよい, つやつやしている.</div><div class=\"def\"><num>③</num> りっぱである, 美しい.</div><div class=\"def\"><num>④</num> 富んでいる, 繁栄している.</div><div class=\"def\"><num>⑤</num> 卓越している, 際立っている.</div><div class=\"def\"><num>⑥</num> (ことば・文体が)洗練されている.</div>\r\n","<div class=\"hw\">nitidiusculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://nitidus\">nitidus</a>]</div><div class=\"def\">もう少しつやつやした.</div>\r\n","<div class=\"hw\">nitidiusculē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nitidiusculus\">nitidiusculus</a>]</div><div class=\"def\">もう少しきちんと[こぎれいに].</div>\r\n","<div class=\"hw\">nitidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[niteo]</div><div class=\"def\"><num>①</num> 光る, 輝く, 明るい.</div><div class=\"def\"><num>②</num> 栄養のよい, つやつやした.</div><div class=\"def\"><num>③</num> 美しい;こぎれいな, きちんとした.</div><div class=\"def\"><num>④</num> 優雅な, 洗練された.</div>\r\n","<div class=\"hw\">nitidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nitidus]</div><div class=\"def\"><num>①</num> 光り輝いて, 明るく.</div><div class=\"def\"><num>②</num> 優雅に, 洗練されて.</div>\r\n","<div class=\"hw\">Nitiobrogēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ニティオブロゲース《Aquitania にいたケルト系一部族》.</div>\r\n","<div class=\"hw\">nitor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[niteo]</div><div class=\"def\"><num>①</num> 光輝, 輝き.</div><div class=\"def\"><num>②</num> つやつやしていること, 光沢.</div><div class=\"def\"><num>③</num> 優雅, 洗練.</div><div class=\"def\"><num>④</num> 卓越, 傑出.</div>\r\n","<div class=\"hw\">nitrum</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">天然のソーダ.</div>\r\n","<div class=\"hw\">nituī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://niteō\">niteo</a>.</div>\r\n","<div class=\"hw\">nitēla<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[niteo]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 輝き;輝くもの.</div><div class=\"def\"><num>②</num> 輝かせるもの.</div>\r\n","<div class=\"hw\">niveus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nix]</div><div class=\"def\"><num>①</num> 雪の.</div><div class=\"def\"><num>②</num> 雪のように白い.</div><div class=\"def\"><num>③</num> 雪のように冷たい;雪で冷やされた.</div><div class=\"def\"><num>⑤</num> 雪におおわれた, 雪の積もった.</div>\r\n","<div class=\"hw\">nivālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nix]</div><div class=\"def\"><num>①</num> 雪の;雪の降る.</div><div class=\"def\"><num>②</num> 雪の積もった, 雪におおわれた.</div><div class=\"def\"><num>③</num> 雪のように白い.</div><div class=\"def\"><num>④</num> 冷たい.</div>\r\n","<div class=\"hw\">nivātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nix]</div><div class=\"def\">雪で冷やされた.</div>\r\n","<div class=\"hw\">nivōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nix\">nix</a>]</div><div class=\"def\">雪の多い;雪をもたらす.</div>\r\n","<div class=\"hw\">nix</div><div class=\"pos\">nivis, <i>f</i></div><div class=\"def\">雪;(<i>pl</i>)降雪</div><div class=\"ex\"><i>capitis nives</i> (<author>H<small>OR</small></author>)<span class=\"ext\">(老人の)白髪.</span></div>\r\n","<div class=\"hw\">nixor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[nitor<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 寄りかかる, もたれる 〈re〉.</div><div class=\"def\"><num>②</num> 骨折る, 奮闘する.</div>\r\n","<div class=\"hw\">nixus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nītor\">nitor<SUP>2</SUP></a>.</div><hr><div class=\"hw\">nixus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 努力, 奮闘.</div><div class=\"def\"><num>②</num> (<i>pl</i>)産みの苦しみ.</div>\r\n","<div class=\"hw\">Nixī</div><div class=\"pos\">-ōrum, <i>m pl</i>(<i>pp</i>)</div><div class=\"ori\">[nitor<SUP>2</SUP>]</div><div class=\"def\">ニクシー《お産を助ける神々》.</div>\r\n","<div class=\"hw\">nocens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[noceo]</div><div class=\"def\"><num>①</num> 有害な, 危険な.</div><div class=\"def\"><num>②</num> 邪悪な, 罪のある, 有罪の 〈re〉.</div><hr><div class=\"hw\">nocens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\">犯罪者, 罪人.</div>\r\n","<div class=\"hw\">nocenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nocens<SUP>1</SUP>]</div><div class=\"def\">有害に, 危険に.</div>\r\n","<div class=\"hw\">nocentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[nocens<SUP>1</SUP>]</div><div class=\"def\">有罪.</div>\r\n","<div class=\"hw\">noceō</div><div class=\"pos\">-ēre -cuī -citum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[<i>cf. </i> nex, neco]</div><div class=\"def\"><num>①</num> 傷つける, 害する, そこなう 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 堕落させる.</div>\r\n","<div class=\"hw\">noctambulismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[nox/ambulo]</div><div class=\"def\">〘病〙夢遊(症).</div>\r\n","<div class=\"hw\">nocte</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"def\">=<a href=\"entry://noctū\">noctu</a>.</div>\r\n","<div class=\"hw\">noctescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[nox]</div><div class=\"def\">(夜のように)暗くなる.</div>\r\n","<div class=\"hw\">noctifer</div><div class=\"pos\">-ferī, <i>m</i></div><div class=\"ori\">[nox/fero]</div><div class=\"def\">宵の明星(=<a href=\"entry://Hesperus\">Hesperus</a>).</div>\r\n","<div class=\"hw\">noctilūca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nox/luceo]</div><div class=\"def\">夜輝くもの(=月).</div>\r\n","<div class=\"hw\">noctivagus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nox/vagus<SUP>1</SUP>]</div><div class=\"def\">夜にさまよう.</div>\r\n","<div class=\"hw\">noctua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nox]</div><div class=\"def\">〘動〙フクロウ(梟)</div><div class=\"ex\"><i>Athenas noctuam mittere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(Minerva に守護される)Athenae へ(女神の聖鳥の)フクロウを送る(=蛇足を加える).</span></div>\r\n","<div class=\"hw\">noctulūcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noctu/luceo]</div><div class=\"def\">夜眠らずにいる.</div>\r\n","<div class=\"hw\">nocturnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noctu]</div><div class=\"def\"><num>①</num> 夜の.</div><div class=\"def\"><num>②</num> 夜に行なわれる.</div><div class=\"def\"><num>③</num> 夜に活動する</div><div class=\"ex\"><i>fur</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">夜盗.</span></div>\r\n","<div class=\"hw\">noctuvigilus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noctu/vigilo]</div><div class=\"def\">夜に見張りをする, 夜眠らずにいる.</div>\r\n","<div class=\"hw\">noctuābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">夜に旅する.</div>\r\n","<div class=\"hw\">noctuīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noctua]</div><div class=\"def\">フクロウの.</div>\r\n","<div class=\"hw\">noctū</div><div class=\"pos\"><i>adv</i>(<i>abl</i>(古形))</div><div class=\"ori\">[nox]</div><div class=\"def\">夜に.</div>\r\n","<div class=\"hw\">noctūria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://nyctūria\">nycturia</a>.</div>\r\n","<div class=\"hw\">nocumentum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[noceo]</div><div class=\"def\">害, 損害.</div>\r\n","<div class=\"hw\">nocuus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noceo]</div><div class=\"def\">有害な.</div>\r\n","<div class=\"hw\">nocīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://noceō\">noceō</a>]</div><div class=\"def\">有害な.</div>\r\n","<div class=\"hw\">Nodīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ノディーヌス《ローマ市近郊の川》.</div>\r\n","<div class=\"hw\">noenu(m)</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ne-/unum]</div><div class=\"def\">《古形》=<a href=\"entry://nōn\">non</a>.</div>\r\n","<div class=\"hw\">nola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">小さな鐘.</div>\r\n","<div class=\"hw\">nolle</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://nōlō\">nolo</a>.</div>\r\n","<div class=\"hw\">noma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙水癌.</div>\r\n","<div class=\"hw\">Nomas</div><div class=\"pos\">-adis, <i>m</i>, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (<i>m</i>)遊牧民.</div><div class=\"def\"><num>②</num> (<i>f</i>)遊牧民の居住地.</div>\r\n","<div class=\"hw\">nomisma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 貨幣, 硬貨(=<a href=\"entry://nummus\">nummus</a>).</div><div class=\"def\"><num>②</num> しるし, 保証.</div>\r\n","<div class=\"hw\">Nomius, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(「牧者」の意)Apollo の添え名.</div>\r\n","<div class=\"hw\">nomos<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">旋律, 楽曲.</div><hr><div class=\"hw\">nomos<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(エジプトの)行政区画.</div>\r\n","<div class=\"hw\">nomē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">腐食性の腫瘍.</div>\r\n","<div class=\"hw\">Norba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ノルバ《Latium の町》.</div>\r\n","<div class=\"hw\">Norbānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Norba の.</div>\r\n","<div class=\"hw\">norma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 定規, 曲尺<SUB>かねじゃく</SUB>.</div><div class=\"def\"><num>②</num> 規範, 規則.</div>\r\n","<div class=\"hw\">normālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://norma\">norma</a>]</div><div class=\"def\">曲尺を使って作られた, 直角の</div><div class=\"ex\"><i>～ angulus</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">直角.</span></div>\r\n","<div class=\"hw\">Nortia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ノルティア《Etruria 人の女神;しばしば運命の女神 Fortuna と同一視される》.</div>\r\n","<div class=\"hw\">noscitābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://noscitō\">noscitō</a>]</div><div class=\"def\">気づく, 認める.</div>\r\n","<div class=\"hw\">noscitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://noscō\">noscō</a>]</div><div class=\"def\"><num>①</num> (詳しく)調べる.</div><div class=\"def\"><num>②</num> 気づく, 認める.</div><div class=\"def\"><num>③</num> よく知っている, 慣れている.</div>\r\n","<div class=\"hw\">noscō</div><div class=\"pos\">-ere nōvī nōtum, <i>tr</i></div><div class=\"def\"><num>①</num> 知る 〈alqd;+間接疑問;+<i>acc c. inf</i>〉.</div><div class=\"def\"><num>②</num> (<i>pf</i>)知っている.</div><div class=\"def\"><num>③</num> よく知る, 精通する;知り合いになる.</div><div class=\"def\"><num>④</num> 検査[調査]する;審理する.</div><div class=\"def\"><num>⑤</num> 確認する, 認識する</div><div class=\"ex\"><i>acciti edicto domini ad res suas noscendas</i> (<author>L<small>IV</small></author>)<span class=\"ext\">所有者たちは自分の財産を確認するために布告によって呼び寄せられた.</span></div><div class=\"def\"><num>⑥</num> 承認する, 認める.</div>\r\n","<div class=\"hw\">nosocomīum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">病院, 診療所.</div>\r\n","<div class=\"hw\">nosologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙疾病分類学.</div>\r\n","<div class=\"hw\">nosse</div><div class=\"pos\"><i>inf pf</i></div><div class=\"def\">=novisse(⇒ <a href=\"entry://noscō\">nosco</a>).</div>\r\n","<div class=\"hw\">nossem</div><div class=\"pos\"><i>subj pf</i></div><div class=\"def\">=novissem(⇒ <a href=\"entry://noscō\">nosco</a>).</div>\r\n","<div class=\"hw\">nostalgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">懐郷, 郷愁.</div>\r\n","<div class=\"hw\">noster<SUP>1</SUP></div><div class=\"pos\">-tra -trum, <i>adj poss</i></div><div class=\"ori\">[nos]</div><div class=\"def\"><num>①</num> 我々の, 我々に属する, 我々による;我々に対する.</div><div class=\"def\"><num>②</num> =<a href=\"entry://meus\">meus</a>.</div><hr><div class=\"hw\">noster<SUP>2</SUP></div><div class=\"pos\">-trī, <i>m</i></div><div class=\"def\"><num>①</num> 我々[私]の友人[主人・息子].</div><div class=\"def\"><num>②</num> (<i>pl</i>)我々の家族[親類・同胞・軍隊・兵].</div><div class=\"def\"><num>③</num> (<i>pl</i>)同じ学派[見解]の人々.</div>\r\n","<div class=\"hw\">nostra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://noster\">noster<SUP>2</SUP></a>]</div><div class=\"def\">我々の家[館]の女主人.</div>\r\n","<div class=\"hw\">nostrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[noster<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 我々の義務[本分].</div><div class=\"def\"><num>②</num> (<i>pl</i>)我々の財産[所有物].</div>\r\n","<div class=\"hw\">nostrās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"ori\">[noster<SUP>1</SUP>]</div><div class=\"def\">わが国(固有)の.</div>\r\n","<div class=\"hw\">nostrātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://nostrās\">nostrās</a>]</div><div class=\"def\">我々のやり方で.</div>\r\n","<div class=\"hw\">nota</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nosco]</div><div class=\"def\"><num>①</num> 目印, 標識.</div><div class=\"def\"><num>②</num> 符合, 記号, 文字.</div><div class=\"def\"><num>③</num> (ローマ市民の名簿中, 監察官がその行状に問題ありと認定した市民の名に付す)不名誉のしるし;処罰;烙印, 汚名, 恥辱.</div><div class=\"def\"><num>④</num> (書物の章句に賛同または反対を示すために付す)しるし.</div><div class=\"def\"><num>⑤</num> 品質, 等級.</div><div class=\"def\"><num>⑥</num> しるし, 表示;暗示;合図.</div><div class=\"def\"><num>⑦</num> 跡, 痕跡;(<i>pl</i>)入れ墨.</div>\r\n","<div class=\"hw\">nothus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 庶出の, 非嫡出の.</div><div class=\"def\"><num>②</num> 雑種の.</div><div class=\"def\"><num>③</num> にせの, まがいの.</div>\r\n","<div class=\"hw\">Notium</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ノティウム, <SUP>*</SUP>-オン《Ionia の Colophon 付近の町と岬》.</div>\r\n","<div class=\"hw\">notula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[nota]</div><div class=\"def\">(小さな)しるし.</div>\r\n","<div class=\"hw\">Notus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 南風.</div><div class=\"def\"><num>②</num> (一般に)風.</div><div class=\"def\"><num>③</num> 南, 南方.</div>\r\n","<div class=\"hw\">notābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[noto]</div><div class=\"def\"><num>①</num> 注目に価する, 注目すべき.</div><div class=\"def\"><num>②</num> 目立つ, 顕著な.</div>\r\n","<div class=\"hw\">notābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://notābilis\">notābilis</a>]</div><div class=\"def\">著しく, 目立って.</div>\r\n","<div class=\"hw\">notāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">目印, 標識.</div>\r\n","<div class=\"hw\">notārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[nota]</div><div class=\"def\">速記者;筆記者.</div>\r\n","<div class=\"hw\">notātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[noto]</div><div class=\"def\"><num>①</num> しるしを付けること;(監察官が)不名誉のしるしを付けること.</div><div class=\"def\"><num>②</num> 記号, 文字.</div><div class=\"def\"><num>③</num> 語源(解釈).</div><div class=\"def\"><num>④</num> 観察, 注目.</div><div class=\"def\"><num>⑤</num> 選抜, 選出.</div>\r\n","<div class=\"hw\">notātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[noto]</div><div class=\"def\">よく知られた, 目立つ;けがれた.</div>\r\n","<div class=\"hw\">notō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nota]</div><div class=\"def\"><num>①</num> しるしを付ける.</div><div class=\"def\"><num>②</num> 語源的解釈をする.</div><div class=\"def\"><num>③</num> (書物の章句に賛同または反対の)記号を付ける.</div><div class=\"def\"><num>④</num> (監察官が市民の名に)不名誉のしるしを付ける;烙印をおす, 汚名をきせる.</div><div class=\"def\"><num>⑤</num> 限定する.</div><div class=\"def\"><num>⑥</num> 識別する, 認識する.</div><div class=\"def\"><num>⑦</num> (ある目的のために)選抜[選別]する.</div><div class=\"def\"><num>⑧</num> (しるしによって)指し示す, 知らせる.</div><div class=\"def\"><num>⑨</num> (記号・ことばによって)表わす.</div><div class=\"def\"><num>⑩</num> 例証する.</div><div class=\"def\"><num>⑪</num> (文字・ことばを)しるす, 書く;書き留める.</div><div class=\"def\"><num>⑫</num> 言及する, 述べる.</div><div class=\"def\"><num>⑬</num> 注目する, 観察する.</div>\r\n","<div class=\"hw\">Nova Via</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ノウァ・ウィア《ローマ市の Palatinus 丘から forum Romanum へ下る道》.</div>\r\n","<div class=\"hw\">novella</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[novellus]</div><div class=\"def\"><num>①</num> 新しく植え付けられたブドウの木.</div><div class=\"def\"><num>②</num> 若木, 若枝.</div>\r\n","<div class=\"hw\">novellus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> (動植物が)若い.</div><div class=\"def\"><num>②</num> 新しい;不慣れの.</div>\r\n","<div class=\"hw\">novellō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://novellus\">novellus</a>]</div><div class=\"def\">ブドウ畑を開墾する.</div>\r\n","<div class=\"hw\">novem</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"def\">9(の).</div>\r\n","<div class=\"hw\">November<SUP>1</SUP>, -bris</div><div class=\"pos\">-bris -bre, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://novem\">novem</a>]</div><div class=\"def\">(ローマ古暦の)9月の;(前153年以降)11月の.</div><hr><div class=\"hw\">November<SUP>2</SUP>, -bris</div><div class=\"pos\">-bris, <i>m</i></div><div class=\"def\">(<i>sc. </i> mensis)(ローマ古暦の)9月;(前153年以降)11月.</div>\r\n","<div class=\"hw\">novendiālis, novem-</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[novem/dies]</div><div class=\"def\"><num>①</num> 9日(間)続く.</div><div class=\"def\"><num>②</num> 9日目に行なわれる.</div>\r\n","<div class=\"hw\">novennis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[novem/annus]</div><div class=\"def\">9歳の.</div>\r\n","<div class=\"hw\">Novensidēs, Novensilēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[novus/insideo]</div><div class=\"def\">外来の神々.</div>\r\n","<div class=\"hw\">noverca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[novus]</div><div class=\"def\">継母.</div>\r\n","<div class=\"hw\">novercor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[noverca]</div><div class=\"def\">継母のようにふるまう.</div>\r\n","<div class=\"hw\">novercālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://noverca\">noverca</a>]</div><div class=\"def\">継母の(ような).</div>\r\n","<div class=\"hw\">Novesium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ノウェシウム《Gallia Belgica の, Rhenus 河岸の要塞都市;現 Neuss》.</div>\r\n","<div class=\"hw\">Noviodūnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ノウィオドゥーヌム《 (1) Bituriges 族の町.(2) Aedui 族の町;現 Nevers.(3) Suessiones 族の町;現 Soissons》.</div>\r\n","<div class=\"hw\">novissima</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[novissimus]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 底, 深み.</div><div class=\"def\"><num>②</num> 最悪の事態.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 終わり, 最後.</div>\r\n","<div class=\"hw\">novissimus</div><div class=\"pos\">-a -um, <i>adj superl</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> 最近の, 最新の.</div><div class=\"def\"><num>②</num> 最後の;臨終の.</div><div class=\"def\"><num>③</num> 最後尾の</div><div class=\"ex\"><i>agmen novissimum</i> (<author>C<small>AES</small></author>)<span class=\"ext\">しんがり, 後衛.</span></div><div class=\"def\"><num>④</num> 最低の, 最下位の.</div><div class=\"def\"><num>⑤</num> 極端な.</div>\r\n","<div class=\"hw\">novissimē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://novissimus\">novissimus</a>]</div><div class=\"def\"><num>①</num> 近ごろ, 最近.</div><div class=\"def\"><num>②</num> 最後に.</div>\r\n","<div class=\"hw\">novitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> 新しさ, 新奇;新奇なこと[もの].</div><div class=\"def\"><num>②</num> 見慣れないこと, 異様.</div><div class=\"def\"><num>③</num> 思いがけないこと, 意外.</div><div class=\"def\"><num>④</num> (ローマ政界の)新人(homo novus)であること.</div><div class=\"def\"><num>⑤</num> (<i>pl</i>)新しい知り合い.</div>\r\n","<div class=\"hw\">Novius</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ノウィウス《ローマ人の氏族名;特に Atella 笑劇の作者(前1世紀初)》.</div>\r\n","<div class=\"hw\">noviēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[novem]</div><div class=\"def\">9回[倍].</div>\r\n","<div class=\"hw\">Novocōmensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Novum Comum の住民.</div>\r\n","<div class=\"hw\">Novum Cōmum</div><div class=\"pos\">-ī -ī, <i>n</i></div><div class=\"def\">ノウゥム・コームム《Gallia Transpadana の町 Comum の 前59年以降の呼称(⇒ <a href=\"entry://Cōmum\">Comum</a>)》.</div>\r\n","<div class=\"hw\">novus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 新しい.</div><div class=\"def\"><num>②</num> 新鮮な, 若い;早い.</div><div class=\"def\"><num>③</num> 見慣れない, 新奇な.</div><div class=\"def\"><num>④</num> 不意の, 意外な.</div><div class=\"def\"><num>⑤</num> </div><div class=\"ex\"><i>novae res</i> (<author>C<small>AES</small></author>)<span class=\"ext\">変革, 革命.</span></div><div class=\"def\"><num>⑥</num> 革命[煽動]的な.</div><div class=\"def\"><num>⑦</num> 最近の.</div><div class=\"def\"><num>⑧</num> 経験のない.</div><div class=\"def\"><num>⑨</num> </div><div class=\"ex\">～ <i>homo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">新人《その家系の中で初めて高位の官職(監察官・執政官・法務官・貴族造営官)に就いた者》.</span></div>\r\n","<div class=\"hw\">novācula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 小刀, ナイフ.</div><div class=\"def\"><num>②</num> かみそり.</div>\r\n","<div class=\"hw\">novāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://novālis\">novālis<SUP>1</SUP></a>]</div><div class=\"def\">(<i>sc. </i> solum)=<a href=\"entry://novālis\">novalis<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">novālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[novus]</div><div class=\"def\">(土地が)休閑の, 休作の.</div><hr><div class=\"hw\">novālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">(<i>sc. </i> terra)</div><div class=\"def\"><num>①</num> 新開懇地.</div><div class=\"def\"><num>②</num> 休閑地.</div><div class=\"def\"><num>③</num> 耕地.</div>\r\n","<div class=\"hw\">novātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[novo]</div><div class=\"def\">〘法〙更改《現債務を消滅させて新債務に代えること》.</div>\r\n","<div class=\"hw\">novātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[novo]</div><div class=\"def\">案出者</div><div class=\"ex\"><i>～ verborum</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">新語を造り出す人.</span></div>\r\n","<div class=\"hw\">novātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://novātor\">novātor</a>]</div><div class=\"def\">更新者《女性》.</div>\r\n","<div class=\"hw\">novātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://novō\">novo</a>.</div>\r\n","<div class=\"hw\">novē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> 新奇な[珍しい]方法で.</div><div class=\"def\"><num>②</num> 当世風に.</div>\r\n","<div class=\"hw\">novēnus</div><div class=\"pos\">-a -um, (通例 <i>pl</i>)<B>novēnī</B> -ae -a, <i>num distrib</i></div><div class=\"ori\">[novem]</div><div class=\"def\">9ずつの.</div>\r\n","<div class=\"hw\">novēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[noveni]</div><div class=\"def\"><num>①</num> 9の部分からなる.</div><div class=\"def\"><num>②</num> (溝が)深さと幅が 3 pedes の.</div>\r\n","<div class=\"hw\">novēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"def\">⇒<a href=\"entry://novēnus\">novenus</a>.</div>\r\n","<div class=\"hw\">novīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> (奴隷が)新しく輸入された[買われた];新参の, 新入りの.</div><div class=\"def\"><num>②</num> 新しく発見[工夫]された.</div>\r\n","<div class=\"hw\">novīciī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://novīcius\">novīcius</a>]</div><div class=\"def\">新しく輸入された[買われた]奴隷たち.</div>\r\n","<div class=\"hw\">novītia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[novitius]</div><div class=\"def\">〘教会〙</div><div class=\"def\"><num>①</num> 新信者《女性》.</div><div class=\"def\"><num>②</num> 修練女.</div>\r\n","<div class=\"hw\">novītius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[novus]</div><div class=\"def\">〘教会〙</div><div class=\"def\"><num>①</num> 新信者.</div><div class=\"def\"><num>②</num> 修練士.</div>\r\n","<div class=\"hw\">novītiātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://novītius\">novītius</a>]</div><div class=\"def\"><num>①</num> 修練期.</div><div class=\"def\"><num>②</num> 修練院.</div>\r\n","<div class=\"hw\">novō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[novus]</div><div class=\"def\"><num>①</num> 新たにする.</div><div class=\"def\"><num>②</num> 新しく作る, 考案[案出]する.</div><div class=\"def\"><num>③</num> (新しいものに)取り替える;〘法〙更改する.</div><div class=\"def\"><num>④</num> 復活させる, 回復させる.</div><div class=\"def\"><num>⑤</num> 変える, 改変する</div><div class=\"ex\"><i>res novare</i> (<author>L<small>IV</small></author>)<span class=\"ext\">革命を起こす, 変革する.</span></div><div class=\"def\"><num>⑥</num> 再び始める, 再開する;(感情・状態を)再び起こさせる.</div><div class=\"def\"><num>⑦</num> 繰り返す.</div>\r\n","<div class=\"hw\">nox</div><div class=\"pos\">noctis, <i>f</i></div><div class=\"def\"><num>①</num> 夜</div><div class=\"ex\"><i>noctes et dies</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">日夜, 絶えず</span></div><div class=\"ex\"><i>nocte</i> (<author>C<small>IC</small></author>)<span class=\"ext\">夜に(=<a href=\"entry://noctū\">noctu</a>).</span></div><div class=\"def\"><num>②</num> (N-)〘神話〙ノクス《夜の神》.</div><div class=\"def\"><num>③</num> 闇, 暗黒.</div><div class=\"def\"><num>④</num> 死.</div><div class=\"def\"><num>⑤</num> 眠り.</div><div class=\"def\"><num>⑥</num> 盲目;無知, 暗愚.</div>\r\n","<div class=\"hw\">noxa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[noceo]</div><div class=\"def\"><num>①</num> 悪事, 悪行.</div><div class=\"def\"><num>②</num> 害, 損害.</div><div class=\"def\"><num>③</num> 罰.</div>\r\n","<div class=\"hw\">noxia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[noxius<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 悪事, 悪行.</div><div class=\"def\"><num>②</num> 害, 損害.</div>\r\n","<div class=\"hw\">noxius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 有害な.</div><div class=\"def\"><num>②</num> 罪を犯した.</div><hr><div class=\"hw\">noxius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">犯罪人, 罪人.</div>\r\n","<div class=\"hw\">noxiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://noxia\">noxia</a>]</div><div class=\"def\"><num>①</num> 有害な.</div><div class=\"def\"><num>②</num> 罪を犯した.</div>\r\n","<div class=\"hw\">noxālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://noxa\">noxa</a>]</div><div class=\"def\">〘法〙損害の, 加害の.</div>\r\n","<div class=\"hw\">nucellus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[nux]</div><div class=\"def\">〘植〙珠心.</div>\r\n","<div class=\"hw\">nuceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nux]</div><div class=\"def\">クルミの木の.</div>\r\n","<div class=\"hw\">nucha</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Arab</i>.]</div><div class=\"def\">〘解〙項<SUB>うなじ</SUB>.</div>\r\n","<div class=\"hw\">nucifrangibulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[nux/frango]</div><div class=\"def\">クルミ割り《歯を指す喜劇の表現》.</div>\r\n","<div class=\"hw\">nucleolus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nucleus\">nucleus</a>]</div><div class=\"def\">〘生物〙核小体.</div>\r\n","<div class=\"hw\">nucleus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[nux]</div><div class=\"def\"><num>①</num> (堅果の)仁<SUB>じん</SUB>.</div><div class=\"def\"><num>②</num> (果実の)種.</div><div class=\"def\"><num>③</num> 核.</div>\r\n","<div class=\"hw\">nucula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[nux]</div><div class=\"def\">〘植〙(小さな)堅果.</div>\r\n","<div class=\"hw\">nudius</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nunc/dies]</div><div class=\"def\">(序数詞とともに)...してから...日目で</div><div class=\"ex\"><i>～ tertius</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">一昨日に.</span></div>\r\n","<div class=\"hw\">nudiustertiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nudius\">nudius</a>/tertius]</div><div class=\"def\">一昨日の.</div>\r\n","<div class=\"hw\">nullib<img class=\"font\" src=\"img/A130.png\"></div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[nullus/ubi]</div><div class=\"def\">どこにも...ない.</div>\r\n","<div class=\"hw\">nullificāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nullificō\">nullificō</a>]</div><div class=\"def\">軽蔑.</div>\r\n","<div class=\"hw\">nullificō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[nullus/facio]</div><div class=\"def\">軽蔑する.</div>\r\n","<div class=\"hw\">nullipara</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙未産婦.</div>\r\n","<div class=\"hw\">nullitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[nullus]</div><div class=\"def\"><num>①</num> 無.</div><div class=\"def\"><num>②</num> 無価値.</div><div class=\"def\"><num>③</num> 無効.</div>\r\n","<div class=\"hw\">nullum</div><div class=\"pos\">nullīus, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nullus\">nullus</a>]</div><div class=\"def\">=<a href=\"entry://nihil\">nihil<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">nullus</div><div class=\"pos\">-a -um(<i>gen</i> nullīus, <i>dat</i> nullī), <i>adj</i></div><div class=\"ori\">[ne-/ullus]</div><div class=\"def\"><num>①</num> ない</div><div class=\"ex\"><i>nullo certo ordine</i> (<author>C<small>AES</small></author>)<span class=\"ext\">整然とした秩序もなく</span></div><div class=\"ex\"><i>～ non</i><span class=\"ext\">あらゆる, すべての</span></div><div class=\"ex\"><i>non ～</i><span class=\"ext\">少なからぬ, かなりの.</span></div><div class=\"def\"><num>②</num> 無意味な, 無価値な, 取るに足らぬ</div><div class=\"ex\"><i>sine his studiis vita nulla est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">これらの考究なしには人生は生きるに値しない.</span></div><div class=\"def\"><num>③</num> 存在しない.</div>\r\n","<div class=\"hw\">nullusdum</div><div class=\"pos\">nulladum nullumdum, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nullus\">nullus</a>/dum<SUP>2</SUP>]</div><div class=\"def\">まだ誰も[何も]...ない.</div>\r\n","<div class=\"hw\">nullātenus</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[<i>cf</i>. eatenus]</div><div class=\"def\">決して[全く]...ない.</div>\r\n","<div class=\"hw\">num</div><div class=\"pos\"><i>adv interrog</i></div><div class=\"def\"><num>①</num> (否定の答を予期する疑問文を導いて)...ではないだろうね</div><div class=\"ex\">～ <i>ista est nostra culpa?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">まさかそれが我々の過失だろうか</span></div><div class=\"ex\">～ <i>quid vis?</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">他に何か用はないだろうね《いとまごいの決まり文句》.</span></div><div class=\"def\"><num>②</num> (間接疑問を導いて)...か(どうか).</div>\r\n","<div class=\"hw\">Num.</div><div class=\"def\">《略》=<a href=\"entry://Numerius\">Numerius</a>.</div>\r\n","<div class=\"hw\">Numa</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ヌマ《<i>～ Pompilius</i>, 前700年頃の伝説的なローマ第2代の王》.</div>\r\n","<div class=\"hw\">Numantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ヌマンティア《Hispania Tarraconensis の町;小 Scipio に攻略された(前133)》.</div>\r\n","<div class=\"hw\">Numantīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Numantia の.</div><div class=\"hw2\"><b>Numantīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Numantia の住民.</div>\r\n","<div class=\"hw\">numella</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(犯罪人・奴隷・家畜用の)鉄の首輪.</div>\r\n","<div class=\"hw\">Numerius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ヌメリウス《 (1) ローマ人の個人名(略形 N(um).).(2) ローマ人の氏族名;特に <i>Q. ～ Rufus</i>, 護民官(前57)》.</div>\r\n","<div class=\"hw\">Numeriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Numerius (2) の.</div>\r\n","<div class=\"hw\">numerus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> nummus]</div><div class=\"def\"><num>①</num> 総数</div><div class=\"ex\"><i>oppida numero ad duodecim</i> (<author>C<small>AES</small></author>)<span class=\"ext\">数で言えば[全部で]12の町.</span></div><div class=\"def\"><num>②</num> 数, 数量 〈+<i>gen</i>;ex+<i>abl</i>〉</div><div class=\"ex\"><i>magnum numerum hostium occidimus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">われわれは多数の敵を殺した.</span></div><div class=\"def\"><num>③</num> (<i>pl</i>)計算, 数学.</div><div class=\"def\"><num>④</num> 兵員, 兵力;数の優勢.</div><div class=\"def\"><num>⑤</num> (必要な)数.</div><div class=\"def\"><num>⑥</num> 〘文〙数.</div><div class=\"def\"><num>⑦</num> 群れ, 集団;群集, 烏合の衆.</div><div class=\"def\"><num>⑧</num> 部隊, 兵団.</div><div class=\"def\"><num>⑨</num> (人やものの)集合体 〈+<i>gen</i>〉</div><div class=\"ex\"><i>legatos ex suo numero ad Caesarem mittunt</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼らは自分たちの中から使者をカエサルのもとへ送る.</span></div><div class=\"def\"><num>⑩</num> 範疇, 部類 〈+<i>gen</i>〉</div><div class=\"ex\"><i>habere alqm numero hostium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を敵とみなす.</span></div><div class=\"def\"><num>⑪</num> (全体を形づくる)部分, 側面, 段階.</div><div class=\"def\"><num>⑫</num> 拍子, リズム</div><div class=\"ex\"><i>in</i> [<i>ad</i>] <i>numerum</i> (<author>L<small>UCR</small> [O<small>V</small>]</author>)<span class=\"ext\">調子を合わせて.</span></div><div class=\"def\"><num>⑬</num> 〘詩〙韻律;詩脚;韻文, 詩.</div><div class=\"def\"><num>⑭</num> 旋律, 調べ.</div><div class=\"def\"><num>⑮</num> <SUP>◇</SUP></div><div class=\"ex\">～ <i>primus</i><span class=\"ext\">〘数〙素数.</span></div>\r\n","<div class=\"hw\">numerābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[numero<SUP>1</SUP>]</div><div class=\"def\">数えられる.</div>\r\n","<div class=\"hw\">numerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[numero<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 計算, 勘定.</div><div class=\"def\"><num>②</num> 支払い.</div>\r\n","<div class=\"hw\">numerātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://numerātus\">numerātus</a>]</div><div class=\"def\">現金.</div>\r\n","<div class=\"hw\">numerātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[numero<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 数えられた;支払われた.</div><div class=\"def\"><num>②</num> 現金の.</div>\r\n","<div class=\"hw\">numerō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[numerus]</div><div class=\"def\"><num>①</num> 数える, 計算する, 合計する</div><div class=\"ex\"><i>senatum numerare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(定足数を充たしているか否かを確認するために)元老院議員(の出席数)を数える.</span></div><div class=\"def\"><num>②</num> 支払う.</div><div class=\"def\"><num>③</num> 数え上げる, 列挙する.</div><div class=\"def\"><num>④</num> 含める, 算入する 〈alqd in re;alqd inter+<i>acc</i>〉.</div><div class=\"def\"><num>⑤</num> (...を...と)みなす, 判断する 〈+2個の <i>acc</i>〉.</div><hr><div class=\"hw\">numerō<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[numerus]</div><div class=\"def\"><num>①</num> ちょうど, ぴったり.</div><div class=\"def\"><num>②</num> 速やかに.</div><div class=\"def\"><num>③</num> 早過ぎて, 時期尚早に.</div>\r\n","<div class=\"hw\">numerōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://numerōsus\">numerōsus</a>]</div><div class=\"def\"><num>①</num> 多数.</div><div class=\"def\"><num>②</num> リズム, 諧調.</div>\r\n","<div class=\"hw\">numerōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://numerus\">numerus</a>]</div><div class=\"def\"><num>①</num> 多数の;多くの部分からなる.</div><div class=\"def\"><num>②</num> 多様な.</div><div class=\"def\"><num>③</num> 大量に生み出す, 多産の.</div><div class=\"def\"><num>④</num> 調和のとれた, リズミカルな.</div>\r\n","<div class=\"hw\">numerōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[numerosus]</div><div class=\"def\"><num>①</num> 数多く;さまざまに.</div><div class=\"def\"><num>②</num> リズミカルに.</div>\r\n","<div class=\"hw\">Numidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Numidia 人.</div>\r\n","<div class=\"hw\">Numidia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ヌミディア《北アフリカにあった王国;前46年からローマの属州;ほぼ現在の Algeria に当たる》.</div>\r\n","<div class=\"hw\">Numidicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Numidia の.</div>\r\n","<div class=\"hw\">Numidiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Numidicus\">Numidicus</a>.</div>\r\n","<div class=\"hw\">Numisius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ヌミシウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Numisiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Numisius の.</div>\r\n","<div class=\"hw\">numisma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"def\">=<a href=\"entry://nomisma\">nomisma</a>.</div>\r\n","<div class=\"hw\">numismatica</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://numisma\">numisma</a>]</div><div class=\"def\">古銭学.</div>\r\n","<div class=\"hw\">Numistrō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">ヌミストロー《Lucania 北部の町》.</div>\r\n","<div class=\"hw\">Numitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">〘伝説〙ヌミトル《Alba Longa の王;Ilia の父で Romulus と Remus の祖父》.</div>\r\n","<div class=\"hw\">Numitōrius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ヌミトーリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">nummulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nummus\">nummus</a>]</div><div class=\"def\">(わずかな)お金.</div>\r\n","<div class=\"hw\">nummulāriolus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nummulārius\">nummulārius<SUP>1</SUP></a>]</div><div class=\"def\">(小口の)両替商.</div>\r\n","<div class=\"hw\">nummulārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nummulus]</div><div class=\"def\">両替の.</div><hr><div class=\"hw\">nummulārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">両替商.</div>\r\n","<div class=\"hw\">nummus</div><div class=\"pos\">-ī, <i>m</i>(<i>pl gen</i> nummūm [nummōrum])</div><div class=\"def\"><num>①</num> 貨幣, 金銭.</div><div class=\"def\"><num>②</num> =<a href=\"entry://sestertius\">sestertius</a>.</div><div class=\"def\"><num>③</num> (わずかな)お金, 一文.</div>\r\n","<div class=\"hw\">nummārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nummus]</div><div class=\"def\"><num>①</num> 貨幣の;金銭の.</div><div class=\"def\"><num>②</num> 買収[賄賂]のきく.</div>\r\n","<div class=\"hw\">nummātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nummus]</div><div class=\"def\">金持ちの, 富裕な.</div>\r\n","<div class=\"hw\">numnam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[num/nam]</div><div class=\"def\">=<a href=\"entry://numne\">numne</a>.</div>\r\n","<div class=\"hw\">numne</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[num/-ne]</div><div class=\"def\">=<a href=\"entry://num\">num 1</a>.</div>\r\n","<div class=\"hw\">numquam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ne-/umquam]</div><div class=\"def\">決して...ない</div><div class=\"ex\"><i>non ～</i><span class=\"ext\">時には, 時々</span></div><div class=\"ex\"><i>～ non</i><span class=\"ext\">常に, いつも.</span></div>\r\n","<div class=\"hw\">numquid</div><div class=\"pos\"><i>adv interrog</i></div><div class=\"ori\">[num/quid]</div><div class=\"def\"><num>①</num> (否定の答を予期する疑問文を導いて)...ではないだろうね.</div><div class=\"def\"><num>②</num> (間接疑問を導いて)...か(どうか).</div>\r\n","<div class=\"hw\">numquis, num quis</div><div class=\"pos\"><i>pron</i>, <i>adj interrog</i></div><div class=\"def\">⇒<a href=\"entry://num\">num</a>, <a href=\"entry://quis\">quis<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">numquī</div><div class=\"pos\"><i>adv interrog</i></div><div class=\"ori\">[num/qui<SUP>3</SUP>]</div><div class=\"def\">ひょっとして...ではないだろうね.</div>\r\n","<div class=\"hw\">Numīcius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ヌミーキウス《ローマ人の氏族名》.</div><hr><div class=\"hw\">Numīcius<SUP>2</SUP>, -cus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ヌミーキウス《Latium の川;そのほとりに Aeneas が埋葬されたという》.</div>\r\n","<div class=\"hw\">nunc</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 今, 現在</div><div class=\"ex\"><i>～ ipsum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ちょうど今.</span></div><div class=\"def\"><num>②</num> (近い過去)今しがた, たった今.</div><div class=\"def\"><num>③</num> (近い未来)今から, すぐに.</div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>～...～</i><span class=\"ext\">ある時は...(また)ある時は..., 時には...時には....</span></div><div class=\"def\"><num>⑤</num> 近ごろ, 現今では.</div><div class=\"def\"><num>⑥</num> (物語の中で)今や, その時.</div><div class=\"def\"><num>⑦</num> (話題を変えて)さて, ところで.</div><div class=\"def\"><num>⑧</num> (相手を促して)さあ, そら.</div><div class=\"def\"><num>⑨</num> このような状況[事情]なので.</div><div class=\"def\"><num>⑩</num> しかし現状[実際]は.</div>\r\n","<div class=\"hw\">nuncin(e)</div><div class=\"def\">《古形》=nuncne(⇒ <a href=\"entry://nunc\">nunc</a>, <a href=\"entry://-ne\">-ne</a>).</div>\r\n","<div class=\"hw\">nuncjam, nunc jam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> (命令などで)今すぐに, 直ちに.</div><div class=\"def\"><num>②</num> (相手を促して)さあ, そら.</div><div class=\"def\"><num>③</num> やっと今, もうすでに.</div>\r\n","<div class=\"hw\">nuncub<img class=\"font\" src=\"img/A130.png\"></div><div class=\"pos\"><i>adv interrog</i></div><div class=\"ori\">[num/ubi]</div><div class=\"def\">(否定の答を予期して)ひょっとしてどこかで...ではないだろうね.</div>\r\n","<div class=\"hw\">nuncupātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nuncupo]</div><div class=\"def\"><num>①</num> 宣誓, 祈願.</div><div class=\"def\"><num>②</num> 〘法〙口頭遺言.</div><div class=\"def\"><num>③</num> 任命, 指名.</div><div class=\"def\"><num>④</num> 名称, 呼称.</div>\r\n","<div class=\"hw\">nuncupātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://nuncupō\">nuncupō</a>]</div><div class=\"def\">命名者.</div>\r\n","<div class=\"hw\">nuncupātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[nuncupo]</div><div class=\"def\">名目的な, いわゆる.</div>\r\n","<div class=\"hw\">nuncupātīvē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nuncupātīvus\">nuncupātīvus</a>]</div><div class=\"def\">名目上は.</div>\r\n","<div class=\"hw\">nuncupō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nomen/capio<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 宣言する.</div><div class=\"def\"><num>②</num> 指名する</div><div class=\"ex\"><i>heredem alqm nuncupare</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ある人を(正式に)相続人に指名する.</span></div><div class=\"def\"><num>③</num> 宣誓する.</div><div class=\"def\"><num>④</num> 名前を呼ぶ, 呼びかける.</div><div class=\"def\"><num>⑤</num> 名づける, 称する.</div>\r\n","<div class=\"hw\">nundinae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[novem/dies]</div><div class=\"def\"><num>①</num> (8(ローマ式の数え方では9)日目ごとの)市日.</div><div class=\"def\"><num>②</num> 市, 市場.</div><div class=\"def\"><num>③</num> 商売, 売買.</div>\r\n","<div class=\"hw\">nundinor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[nundinae]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 市で売り買いする.</div><div class=\"def\"><num>②</num> 群がる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 売買する 〈alqd〉.</div><div class=\"def\"><num>②</num> 取引によって手に入れる, 買う 〈alqd ab alqo〉.</div><div class=\"def\"><num>③</num> 売り払う, 売却する 〈alqd〉.</div>\r\n","<div class=\"hw\">nundinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[novem/dies]</div><div class=\"def\">市日と次の市日の間の期間(=8日間)</div><div class=\"ex\"><i>～ trinum</i><span class=\"ext\">(a) (<author>C<small>IC</small></author>)24日間《法案の提出から票決までに置かれるべき最低の日数》; (b) (<author>L<small>IV</small></author>) 市の3日目.</span></div>\r\n","<div class=\"hw\">nundinālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nundinae\">nundinae</a>]</div><div class=\"def\">市日の.</div>\r\n","<div class=\"hw\">nundinārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nundinae]</div><div class=\"def\">市の開かれる.</div>\r\n","<div class=\"hw\">nundinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nundinor]</div><div class=\"def\">商売, 売買.</div>\r\n","<div class=\"hw\">nundinātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://nundinor\">nundinor</a>]</div><div class=\"def\">市で売り買いする人;商人.</div>\r\n","<div class=\"hw\">nunqu-</div><div class=\"def\">⇒numqu-.</div>\r\n","<div class=\"hw\">nuntia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nuntius]</div><div class=\"def\">使者《女性》.</div>\r\n","<div class=\"hw\">nuntium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">通知, 通達.</div>\r\n","<div class=\"hw\">nuntius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nuntium\">nuntium</a>]</div><div class=\"def\"><num>①</num> 知らせる, 伝える 〈+<i>gen</i>〉.</div><div class=\"def\"><num>②</num> 予告[警告]する 〈+<i>gen</i>〉.</div><hr><div class=\"hw\">nuntius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 使者;報告者.</div><div class=\"def\"><num>②</num> 通知, 通達;報告.</div>\r\n","<div class=\"hw\">nuntiātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nuntio]</div><div class=\"def\"><num>①</num> (卜占官による)予兆の告知.</div><div class=\"def\"><num>②</num> 通知, 告示.</div>\r\n","<div class=\"hw\">nuntiātor</div><div class=\"pos\">-oris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://nuntiō\">nuntiō</a>]</div><div class=\"def\">通知者.</div>\r\n","<div class=\"hw\">nuntiō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://nuntium\">nuntium</a>]</div><div class=\"def\"><num>①</num> 知らせる, 報告する, 伝える 〈alci alqd;+<i>acc c. inf</i>〉.</div><div class=\"def\"><num>②</num> 指示[指図]する 〈ut, ne;+<i>inf</i>〉.</div><div class=\"def\"><num>③</num> 予告[警告]する</div><div class=\"ex\"><i>clamor qui fera nuntiat arma</i> (<author>O<small>V</small></author>)<span class=\"ext\">無情な戦いを予告するどよめき.</span></div><div class=\"def\"><num>④</num> (卜占官が)予兆を告げる.</div>\r\n","<div class=\"hw\">nupsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nūbō\">nubo</a>.</div>\r\n","<div class=\"hw\">nupta</div><div class=\"pos\">-ae, <i>f</i>(<i>pp</i>)</div><div class=\"ori\">[nubo]</div><div class=\"def\">結婚した女, 妻</div><div class=\"ex\"><i>nova ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">新婦.</span></div>\r\n","<div class=\"hw\">nuptiae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[nubo]</div><div class=\"def\">結婚, 婚姻;結婚式, 婚礼.</div>\r\n","<div class=\"hw\">nuptiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nuptiae\">nuptiae</a>]</div><div class=\"def\">結婚(式)の.</div>\r\n","<div class=\"hw\">nuptus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nūbō\">nubo</a>.</div><hr><div class=\"hw\">nuptus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">とつぐこと, 結婚.</div>\r\n","<div class=\"hw\">Nursia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ヌルシア《Sabini 族の町》.</div>\r\n","<div class=\"hw\">Nursīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nursia の.</div><div class=\"hw2\"><b>Nursīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Nursia の住民.</div>\r\n","<div class=\"hw\">nurus</div><div class=\"pos\">-ūs, <i>f</i></div><div class=\"def\"><num>①</num> 義理の娘, 嫁.</div><div class=\"def\"><num>②</num> 《詩》若い既婚の女性.</div>\r\n","<div class=\"hw\">nuscītiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">=<a href=\"entry://luscītiō\">luscitio</a>.</div>\r\n","<div class=\"hw\">nusquam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ne-/usquam]</div><div class=\"def\"><num>①</num> どこにも...ない;どこへも...(し)ない</div><div class=\"ex\"><i>non ～</i><span class=\"ext\">ところどころに, あちこちに</span></div><div class=\"ex\"><i>～ non</i><span class=\"ext\">いたるところに, どこにも</span></div><div class=\"ex\">～ <i>esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">存在しない.</span></div><div class=\"def\"><num>②</num> いたずらに, むなしく.</div><div class=\"def\"><num>③</num> どんな場合にも[決して]...(し)ない.</div>\r\n","<div class=\"hw\">nux</div><div class=\"pos\">nucis, <i>f</i></div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> 堅果, ナッツ《クルミ・アーモンド・ヘーゼルナッツなど》</div><div class=\"ex\"><i>cassa ～</i> (<author>H<small>OR</small></author>)<span class=\"ext\">実のないクルミ(=つまらぬもの).</span></div><div class=\"def\"><num>②</num> 堅果をつける木.</div><div class=\"def\"><num>③</num> 球果<SUB>きゅうか</SUB>.</div>\r\n","<div class=\"hw\">nyctalops</div><div class=\"pos\">-ōpis, <i>m</i>, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (<i>m</i>)夜盲症患者.</div><div class=\"def\"><num>②</num> (<i>f</i>)=<a href=\"entry://nyctēgreton\">nyctegreton</a>.</div>\r\n","<div class=\"hw\">nyctalōpia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙夜盲症, 鳥目.</div>\r\n","<div class=\"hw\">Nyctelius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bacchus の呼称の一つ《その祭儀が夜間行なわれたことから》.</div>\r\n","<div class=\"hw\">Nycteus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニュクテウス《Antiopa の父》.</div>\r\n","<div class=\"hw\">nycticorax</div><div class=\"pos\">-acis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">夜行性のカラス(烏).</div>\r\n","<div class=\"hw\">Nyctimenē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニュクティメネー《Lesbos 島の王 Epopeus の娘;父と交わってフクロウに変身させられた》.</div>\r\n","<div class=\"hw\">nyctēgreton</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙夜に光を発するという植物.</div>\r\n","<div class=\"hw\">Nyctēis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">Nycteus の娘(=<a href=\"entry://Antiopa\">Antiopa</a>).</div>\r\n","<div class=\"hw\">nyctūria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙夜間多尿(症).</div>\r\n","<div class=\"hw\">nympha</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙ニンフ《海・川・泉・山・森などに住む少女の姿をした精》.</div><div class=\"def\"><num>②</num> 水.</div><div class=\"def\"><num>③</num> 若妻;少女, おとめ.</div><div class=\"def\"><num>④</num> 〘昆〙若虫;さなぎ.</div>\r\n","<div class=\"hw\">nymphaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙スイレン(睡蓮).</div>\r\n","<div class=\"hw\">nymphaeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニンフにささげられた神殿[洞穴].</div>\r\n","<div class=\"hw\">Nymphaeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニュンパエウム, <SUP>*</SUP>-パイオン《Illyria の岬と港町》.</div>\r\n","<div class=\"hw\">nymphomania</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙女子色情(症).</div>\r\n","<div class=\"hw\">nymphālis</div><div class=\"pos\">-is, -e <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[nympha]</div><div class=\"def\">泉の.</div>\r\n","<div class=\"hw\">nystagmus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘医〙眼振, 眼(球)振盪.</div>\r\n","<div class=\"hw\">Nȳsa<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニューサ《Aristaeus の娘で Bacchus の乳母の一人》.</div><hr><div class=\"hw\">Nȳsa<SUP>2</SUP>, Nyssa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニューサ《 (1) Caria の町.(2) Bacchus が生まれたという India の伝説的な山;その山に近い同名の町》.</div>\r\n","<div class=\"hw\">Nȳsaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Nysa<SUP>2</SUP> (1) の.</div><div class=\"def\"><num>②</num> Nysa 山の;《詩》Bacchus の.</div>\r\n","<div class=\"hw\">Nȳsaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Nysa<SUP>2</SUP> (1) の住民.</div>\r\n","<div class=\"hw\">Nȳseus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"def\">Nysa 山の人《Bacchus の呼称の一つ》.</div>\r\n","<div class=\"hw\">Nȳsias</div><div class=\"pos\">-adis [-ados], <i>adj f</i></div><div class=\"def\">=<a href=\"entry://Nȳsēis\">Nyseis</a>.</div>\r\n","<div class=\"hw\">Nȳsigena</div><div class=\"pos\">-ae, <i>adj m</i></div><div class=\"ori\">[Nysa<SUP>2</SUP>/gigno]</div><div class=\"def\">Nysa 山で生まれた.</div>\r\n","<div class=\"hw\">Nȳsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Nȳsaeus\">Nysaeus 2</a>.</div>\r\n","<div class=\"hw\">Nȳsēis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Nysa 山の;Bacchus の.</div>\r\n","<div class=\"hw\">Nȳsēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Nȳsaeus\">Nysaeus 2</a>.</div>\r\n","<div class=\"hw\">Nāicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nais の.</div>\r\n","<div class=\"hw\">Nāis</div><div class=\"pos\">-idis [-idos], <B>Nāias</B> -adis [-ados], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> ナーイス, ナーイアス《川・泉のニンフ》.</div><div class=\"def\"><num>②</num> (一般に)ニンフ.</div>\r\n","<div class=\"hw\">nānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> こびと.</div><div class=\"def\"><num>②</num> (浅く広い)容器.</div>\r\n","<div class=\"hw\">nāpus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘植〙カブラの一種.</div>\r\n","<div class=\"hw\">nāpy</div><div class=\"pos\">-yos, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">カラシ.</div>\r\n","<div class=\"hw\">nāpīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nāpus\">nāpus</a>]</div><div class=\"def\">カブラ畑.</div>\r\n","<div class=\"hw\">Nār</div><div class=\"pos\">Nāris, <i>m</i></div><div class=\"def\">ナール《Umbria の川;Tiberis 川の支流;現 Nera》.</div>\r\n","<div class=\"hw\">nāris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>cf. </i> nasus]</div><div class=\"def\"><num>①</num> 鼻;(<i>pl</i>)鼻孔.</div><div class=\"def\"><num>②</num> 嗅覚.</div><div class=\"def\"><num>③</num> 勘, 洞察力.</div><div class=\"def\"><num>④</num> 軽蔑, 怒り.</div><div class=\"def\"><num>⑤</num> 開口部.</div>\r\n","<div class=\"hw\">nārus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://gnārus\">gnarus</a>.</div>\r\n","<div class=\"hw\">Nārycia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《詩》ナーリュキア《Bruttii の町 Locri Epizephyrii》.</div>\r\n","<div class=\"hw\">Nārycius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 《詩》Narycum の</div><div class=\"ex\"><i>heros</i> ～ (<author>O<small>V</small></author>)<span class=\"ext\">Oileus の子 Ajax.</span></div><div class=\"def\"><num>②</num> Narycia の.</div>\r\n","<div class=\"hw\">Nārycum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナーリュクム, <SUP>*</SUP>-クス《ギリシア中部の Locris の町》.</div>\r\n","<div class=\"hw\">Nāsidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ナーシディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Nāsidiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nasidius の.</div>\r\n","<div class=\"hw\">nāsociliāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙鼻毛様体の.</div>\r\n","<div class=\"hw\">nāsofrontālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙鼻前頭の.</div>\r\n","<div class=\"hw\">nāsolacrimālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙鼻涙の.</div>\r\n","<div class=\"hw\">nāsopalātīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙鼻口蓋の.</div>\r\n","<div class=\"hw\">Nāsos, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ナーソス《「島」の意;Syracusae 市の一部》.</div>\r\n","<div class=\"hw\">nāsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">《古形》=<a href=\"entry://nāsus\">nasus</a>.</div>\r\n","<div class=\"hw\">nāsus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> naris]</div><div class=\"def\"><num>①</num> 鼻</div><div class=\"ex\"><i>alqm naso suspendere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">ある人に対して鼻を上に向ける(=軽蔑する).</span></div><div class=\"def\"><num>②</num> 機智.</div><div class=\"def\"><num>③</num> (容器の)注ぎ口.</div>\r\n","<div class=\"hw\">nāsālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[nasus]</div><div class=\"def\">鼻の[に関する].</div>\r\n","<div class=\"hw\">Nāsīca</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ナーシーカ《ローマ人の家名;特に <i>P. Cornelius Scipio ～</i>, 執政官(前191)》.</div>\r\n","<div class=\"hw\">Nāsō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[nasus]</div><div class=\"def\">ナーソー《ローマ人の家名;特に <i>P. Ovidius ～</i> ⇒ <a href=\"entry://Ovidius\">Ovidius</a>》.</div>\r\n","<div class=\"hw\">nāsūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nasus]</div><div class=\"def\"><num>①</num> 大鼻の.</div><div class=\"def\"><num>②</num> 機智に富んだ, 辛辣な.</div>\r\n","<div class=\"hw\">nāsūtē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nāsūtus\">nāsūtus</a>]</div><div class=\"def\">機智に富んで, 辛辣に.</div>\r\n","<div class=\"hw\">nāta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[natus]</div><div class=\"def\">娘.</div>\r\n","<div class=\"hw\">nātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nascor]</div><div class=\"def\"><num>①</num> 出生, 誕生.</div><div class=\"def\"><num>②</num> 民族, 国民.</div><div class=\"def\"><num>③</num> 組, 集団.</div><div class=\"def\"><num>④</num> 産地.</div>\r\n","<div class=\"hw\">nātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[nascor]</div><div class=\"def\"><num>①</num> (...から)生まれた, 生じた 〈+<i>abl</i>;a [ex] re〉.</div><div class=\"def\"><num>②</num> ...歳の[で]</div><div class=\"ex\"><i>plus triginta annis ～ sum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私は30過ぎだ.</span></div><div class=\"def\"><num>③</num> (...として, ...をもって)生まれた, 生まれながらの 〈+<i>dat</i>;ad [in] alqd〉</div><div class=\"ex\">～ <i>huic imperio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">この帝国(ローマ)に奉仕すべく生まれた.</span></div><hr><div class=\"hw\">nātus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 息子.</div><div class=\"def\"><num>②</num> (<i>pl</i>)子供たち.</div><hr><div class=\"hw jl\"><SUP>*</SUP>nātus<SUP>3</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">(用例は <i>sg abl</i> nātū のみ)</div><div class=\"ori\">[nascor]</div><div class=\"def\">年齢</div><div class=\"ex\"><i>grandis natu</i> (<author>C<small>IC</small></author>)<span class=\"ext\">高齢の</span></div><div class=\"ex\"><i>minimus natu</i> (<author>C<small>IC</small></author>)<span class=\"ext\">最年少の.</span></div>\r\n","<div class=\"hw\">nātāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[natalis<SUP>1</SUP>]</div><div class=\"def\">誕生[出生]地.</div>\r\n","<div class=\"hw\">nātālicia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[natalicius]</div><div class=\"def\">誕生日を祝う宴会.</div>\r\n","<div class=\"hw\">nātālicium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nātālicius\">nātālicius</a>]</div><div class=\"def\">誕生日の贈り物.</div>\r\n","<div class=\"hw\">nātālicius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nātālis\">nātālis<SUP>1</SUP></a>]</div><div class=\"def\">誕生(日)の.</div>\r\n","<div class=\"hw\">nātālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[natus]</div><div class=\"def\"><num>①</num> 誕生の, 出生の</div><div class=\"ex\"><i>dies</i> ～ (<author>P<small>LAUT</small></author>)<span class=\"ext\">誕生日</span></div><div class=\"ex\"><i>solum natale</i> (<author>O<small>V</small></author>)<span class=\"ext\">出生地, 生まれ故郷.</span></div><div class=\"def\"><num>②</num> 生まれつきの, 生得の.</div><hr><div class=\"hw\">nātālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 誕生日;(例年の)記念日.</div><div class=\"def\"><num>②</num> 出生[誕生]地.</div><div class=\"def\"><num>③</num> 出生, 誕生;発生, 起源.</div><div class=\"def\"><num>④</num> (<i>pl</i>)生まれ, 血統.</div>\r\n","<div class=\"hw\">nātīvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nātīvus\">nātīvus</a>]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 出生, 誕生.</div><div class=\"def\"><num>②</num> 起源.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 世代.</div>\r\n","<div class=\"hw\">nātīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nascor]</div><div class=\"def\"><num>①</num> 生まれた, 生じた.</div><div class=\"def\"><num>②</num> 生まれつきの, 生得の.</div><div class=\"def\"><num>③</num> 自然のままの, 人工的でない.</div><div class=\"def\"><num>④</num> 土着の, その土地固有の.</div>\r\n","<div class=\"hw\">nātū</div><div class=\"pos\"><i>m sg abl</i></div><div class=\"def\">⇒<a href=\"entry://nātus\">natus<SUP>3</SUP></a>.</div>\r\n","<div class=\"hw\">nātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nascor]</div><div class=\"def\"><num>①</num> 出生.</div><div class=\"def\"><num>②</num> 自然.</div><div class=\"def\"><num>③</num> 素質, 天性.</div><div class=\"def\"><num>④</num> 特徴, 性質;性格, 気質.</div><div class=\"def\"><num>⑤</num> 本能.</div><div class=\"def\"><num>⑥</num> 自然の理法[秩序].</div><div class=\"def\"><num>⑦</num> 自然界, 万物, 森羅万象.</div><div class=\"def\"><num>⑧</num> 生殖器.</div>\r\n","<div class=\"hw\">nātūrāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nātūrālis\">nātūrālis</a>]</div><div class=\"def\"><num>①</num> (婉曲的に)陰部;排泄物.</div><div class=\"def\"><num>②</num> 特徴.</div>\r\n","<div class=\"hw\">nātūrālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[natura]</div><div class=\"def\"><num>①</num> 自然の, 天然の.</div><div class=\"def\"><num>②</num> 血のつながった, 実の.</div><div class=\"def\"><num>③</num> 自然界の.</div><div class=\"def\"><num>④</num> 自然な, 本来の;生まれつきの, 生来の</div><div class=\"ex\">～ <i>societas inter homines</i> (<author>C<small>IC</small></author>)<span class=\"ext\">人間同士の自然な結びつき</span></div><div class=\"ex\"><i>jus naturale</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自然法.</span></div><div class=\"def\"><num>⑤</num> 普通の, 当然の.</div><div class=\"def\"><num>⑥</num> 特徴的な, 典型的な.</div>\r\n","<div class=\"hw\">nātūrāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://nātūrālis\">nātūrālis</a>]</div><div class=\"def\"><num>①</num> 本来, 生まれつき.</div><div class=\"def\"><num>②</num> 自然に, ひとりでに.</div><div class=\"def\"><num>③</num> 本性に従って.</div><div class=\"def\"><num>④</num> 普通に.</div>\r\n","<div class=\"hw\">Nāva</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ナーウァ《Germania の Rhenus 川の支流;現 Nahe》.</div>\r\n","<div class=\"hw\">nāvicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[navis]</div><div class=\"def\">小舟.</div>\r\n","<div class=\"hw\">nāviculāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[navicularius<SUP>1</SUP>]</div><div class=\"def\">(<i>sc. </i> res)海運業.</div>\r\n","<div class=\"hw\">nāviculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[navicula]</div><div class=\"def\"><num>①</num> 海運業の.</div><div class=\"def\"><num>②</num> 〘解〙舟状(骨)の.</div>\r\n","<div class=\"hw\">nāviculārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[navicula]</div><div class=\"def\"><num>①</num> 小舟の.</div><div class=\"def\"><num>②</num> 船長の.</div><hr><div class=\"hw\">nāviculārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">船主;船長.</div>\r\n","<div class=\"hw\">nāvifragus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[navis/frango]</div><div class=\"def\">難船させる.</div>\r\n","<div class=\"hw\">nāviger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[navis/gero]</div><div class=\"def\">船を運ぶ, 航行できる.</div>\r\n","<div class=\"hw\">nāvigiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://nāvigium\">nāvigium</a>]</div><div class=\"def\">=<a href=\"entry://nāvicula\">navicula</a>.</div>\r\n","<div class=\"hw\">nāvigium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nāvigō\">nāvigō</a>]</div><div class=\"def\">船, 船舶.</div>\r\n","<div class=\"hw\">nāvigābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[navigo]</div><div class=\"def\">航行できる.</div>\r\n","<div class=\"hw\">nāvigātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[navigo]</div><div class=\"def\">航海, 航行.</div>\r\n","<div class=\"hw\">nāvigātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[navigo]</div><div class=\"def\">航海[航行]者.</div>\r\n","<div class=\"hw\">nāvigātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nāvigō\">navigo</a>.</div>\r\n","<div class=\"hw\">nāvigō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://nāvis\">nāvis</a>/ago]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 航海する, 船旅をする.</div><div class=\"def\"><num>②</num> 泳ぐ.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)航行する, 渡航する.</div>\r\n","<div class=\"hw\">nāvis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 船</div><div class=\"ex\"><i>～ longa</i> (<author>C<small>AES</small></author>)<span class=\"ext\">軍船, 軍艦</span></div><div class=\"ex\"><i>～ oneraria</i> (<author>C<small>AES</small></author>)<span class=\"ext\">貨物船, 輸送船.</span></div><div class=\"def\"><num>②</num> (N-)(<i>sc</i>. Argolica)〘天〙アルゴー(Argo)座.</div>\r\n","<div class=\"hw\">nāvita</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">《古形・詩》=<a href=\"entry://nauta\">nauta</a>.</div>\r\n","<div class=\"hw\">nāviter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[navus]</div><div class=\"def\"><num>①</num> 熱心[勤勉]に.</div><div class=\"def\"><num>②</num> 完全に, 全く</div><div class=\"ex\"><i>bene et</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">完全に.</span></div>\r\n","<div class=\"hw\">nāvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[navus]</div><div class=\"def\">勤勉, 熱心.</div>\r\n","<div class=\"hw\">nāvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">熱心な, 勤勉な.</div>\r\n","<div class=\"hw\">nāvāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nāvālis\">nāvālis</a>]</div><div class=\"def\"><num>①</num> 造船所, ドック, 船渠.</div><div class=\"def\"><num>②</num> (<i>pl</i>)(船の)索具.</div>\r\n","<div class=\"hw\">nāvālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[navis]</div><div class=\"def\"><num>①</num> 船の.</div><div class=\"def\"><num>②</num> 海戦の, 海軍の</div><div class=\"ex\"><i>socii navales</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ローマの海軍で水夫・こぎ手をつとめた植民市や同盟市の出身者</span></div><div class=\"ex\"><i>res</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">海戦.</span></div>\r\n","<div class=\"hw\">nāvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[navus]</div><div class=\"def\">熱心に, 勤勉に.</div>\r\n","<div class=\"hw\">nāvō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://nāvus\">nāvus</a>]</div><div class=\"def\"><num>①</num> 専心する, 熱心に行なう</div><div class=\"ex\"><i>operam navare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">忙しく働く, 専念する.</span></div><div class=\"def\"><num>②</num> なし遂げる, 達成する.</div>\r\n","<div class=\"hw\">nē<SUP>1</SUP></div><div class=\"pos\"><i>int</i></div><div class=\"def\">(代名詞の前で用いられる)本当に, 実に, 確かに.</div><hr><div class=\"hw\">nē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>adv</i>)</div><div class=\"def\"><num>①</num> (語句を否定して)...しない, ...でない</div><div class=\"ex\"><i>ne...quidem</i><span class=\"ext\">決して...でない, ...でさえない.</span></div><div class=\"def\"><num>②</num> 〈+<i>impr</i>;+<i>subj</i>〉(命令)...するな</div><div class=\"ex\">～ <i>timete</i> (<author>L<small>IV</small></author>)<span class=\"ext\">恐れるな</span></div><div class=\"ex\">～ <i>me attigas</i> (<author>T<small>ER</small></author>)<span class=\"ext\">私に触らないで</span></div><div class=\"ex\">～ <i>feceris</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">そうしてはいけない.</span></div><div class=\"def\"><num>③</num> 〈+<i>subj</i>〉(祈願)...(し)ないように</div><div class=\"ex\"><i>a, te</i> ～ <i>frigora laedant!</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">ああ, 寒さがあなたをそこなわないように!</span></div><div class=\"def\"><num>④</num> 〈+<i>subj</i>〉(譲歩)...としても</div><div class=\"ex\">～ <i>sit sane summum malum dolor</i>;<i>malum certe est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">いかにも苦痛は最大の害悪ではないとしても, ともかく害悪にはちがいない.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>conj</i>)〈+<i>subj</i>〉</div><div class=\"def\"><num>①</num> (目的を表わす)...しないように, ...するといけないから</div><div class=\"ex\"><i>abeo a te, ～ quid tecum consili commisceam</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">おまえとはおさらばだ, おまえの計画に巻き込まれたくないからな.</span></div><div class=\"def\"><num>②</num> (命令・忠告・要求)...しないように</div><div class=\"ex\"><i>imperavit</i> ～ <i>injussu suo concurrerent</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は自分の号令がないうちは突撃しないように命令した.</span></div><div class=\"def\"><num>③</num> (恐怖・危惧)...ではないかと, ...(する)ことを</div><div class=\"ex\"><i>metu ～ amitteret praemissas jam cohortes</i> (<author>T<small>AC</small></author>)<span class=\"ext\">すでに先発させた歩兵を失うのではないかと恐れて.</span></div><div class=\"def\"><num>④</num> (努力・注意)...しないように</div><div class=\"ex\"><i>fac ～ destiteris scribere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私に手紙を書くのをやめないようにしてください.</span></div><div class=\"def\"><num>⑤</num> (妨害・抵抗)...(する)ことを</div><div class=\"ex\"><i>sententiam ～ diceret, recusavit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は意見を述べることを拒んだ.</span></div>\r\n","<div class=\"hw\">nēcub<img class=\"font\" src=\"img/A130.png\"></div><div class=\"ori\">[ne<SUP>2</SUP>/<SUP>*</SUP>cubi(<i>cf</i>. alicubi)]</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">〈+<i>subj</i>〉どこ[どんな場合]にも...ないように.</div>\r\n","<div class=\"hw\">nēcunde</div><div class=\"ori\">[ne<SUP>2</SUP>/<SUP>*</SUP>cunde(<i>cf</i>. unde)]</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">〈+<i>subj</i>〉どこからも...ないように.</div>\r\n","<div class=\"hw\">nēdum</div><div class=\"ori\">[ne<SUP>2</SUP>/dum<SUP>2</SUP>]</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">〈+<i>subj</i>〉いわんや[まして, なおさら]...でない.</div>\r\n","<div class=\"hw\">Nēleus<SUP>1</SUP></div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ネーレウス《Pylus の王で Nestor の父》.</div>\r\n","<div class=\"hw\">Nēlēius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Nēlīdēs\">Nelides</a>.</div><hr><div class=\"hw\">Nēlēius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Neleus の.</div><div class=\"def\"><num>②</num> 《詩》Nestor の.</div>\r\n","<div class=\"hw\">Nēlēus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Neleus の.</div>\r\n","<div class=\"hw\">Nēlīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Neleus の子孫(=<a href=\"entry://Nestōr\">Nestor</a>).</div>\r\n","<div class=\"hw\">nēmō</div><div class=\"pos\">(<i>gen</i> nullīus, <i>dat</i> nēminī, <i>acc</i> nēminem, <i>abl</i> nullō), <i>m</i>(<i>f</i>)</div><div class=\"ori\">[ne<SUP>2</SUP>/homo]</div><div class=\"def\"><num>①</num> 誰も...ない</div><div class=\"ex\"><i>～ alius</i><span class=\"ext\">他に誰も...ない</span></div><div class=\"ex\">～ <i>unus</i><span class=\"ext\">一人も...ない</span></div><div class=\"ex\"><i>non ～</i><span class=\"ext\">何人か</span></div><div class=\"ex\"><i>～ non</i><span class=\"ext\">各人, 誰もみな.</span></div><div class=\"def\"><num>②</num> 取るに足らぬ人, 無名の人.</div><div class=\"def\"><num>③</num> (形容詞的に)=<a href=\"entry://nullus\">nullus</a>.</div>\r\n","<div class=\"hw\">nēnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 哀悼歌, 挽歌.</div><div class=\"def\"><num>②</num> 呪文.</div><div class=\"def\"><num>③</num> (一般に)歌.</div><div class=\"def\"><num>④</num> (<i>pl</i>)くだらないもの, がらくた.</div>\r\n","<div class=\"hw\">nēpenthes</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">悲しみを取り除くと考えられた薬.</div>\r\n","<div class=\"hw\">nēquam<SUP>1</SUP></div><div class=\"pos\"><i>indecl adj</i>(<i>comp</i> nēquior, <i>superl</i> nēquissimus)</div><div class=\"ori\">[ne<SUP>2</SUP>/quam]</div><div class=\"def\"><num>①</num> 役に立たない, 価値のない.</div><div class=\"def\"><num>②</num> 放埒な, 邪悪な.</div><div class=\"def\"><num>③</num> いたずら好きな.</div><hr><div class=\"hw\">nēquam<SUP>2</SUP></div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">危害, わるさ.</div>\r\n","<div class=\"hw\">nēquandō, nē quandō</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">決して...(し)ないように.</div>\r\n","<div class=\"hw\">nēquior</div><div class=\"pos\">-or -ius, <i>adj comp</i></div><div class=\"def\">⇒<a href=\"entry://nēquam\">nequam<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">nēquissimus</div><div class=\"pos\">-a -um, <i>adj superl</i></div><div class=\"def\">⇒<a href=\"entry://nēquam\">nequam<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">nēquiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nequam<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> まずく;失敗して, 不首尾に.</div><div class=\"def\"><num>②</num> 下劣に, 邪悪に.</div>\r\n","<div class=\"hw\">nēquitia</div><div class=\"pos\">-ae, <B>-ēs</B> -ēī, <i>f</i></div><div class=\"ori\">[nequam<SUP>1</SUP>]</div><div class=\"def\">放蕩, ふしだら, 不品行.</div>\r\n","<div class=\"hw\">nēquāquam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ne<SUP>2</SUP>/quisquam]</div><div class=\"def\">決して...ない.</div>\r\n","<div class=\"hw\">nēquīquam, nēquicquam, necquicquam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> むだに, いたずらに.</div><div class=\"def\"><num>②</num> 根拠なく, 理由なく.</div><div class=\"def\"><num>③</num> 罰を受けずに.</div>\r\n","<div class=\"hw\">Nēreus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙ネーレウス《海神;Oceanus と Tethys の息子で Doris の夫;Nereis たちの父》.</div><div class=\"def\"><num>②</num> 《詩》海.</div>\r\n","<div class=\"hw\">Nēritius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》Neritos の;Ithaca の;Ulixes の.</div>\r\n","<div class=\"hw\">Nēritos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネーリトス《Ithaca 島の山》.</div>\r\n","<div class=\"hw\">Nērēis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ネーレーイス《Nereus と Doris の娘たちの一人;海のニンフ》.</div>\r\n","<div class=\"hw\">Nērēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nereus の.</div>\r\n","<div class=\"hw\">Nērīnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://Nērēis\">Nereis</a>.</div>\r\n","<div class=\"hw\">Nēsis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ネーシス《Puteoli と Neapolis の間にある小島;現 Nisida》.</div>\r\n","<div class=\"hw\">Nētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ネートゥム《Sicilia 島の町;Syracusae の南西にあった》.</div>\r\n","<div class=\"hw\">nētus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://neō\">neo</a>.</div><hr><div class=\"hw\">nētus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(紡ぎ)糸.</div>\r\n","<div class=\"hw\">nētē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(四音音階の)最高音.</div>\r\n","<div class=\"hw\">Nētīnensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Nētīnī\">Netini</a>.</div>\r\n","<div class=\"hw\">Nētīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Netum の住民.</div>\r\n","<div class=\"hw\">nēve, neu</div><div class=\"pos\"><i>conj</i>, <i>adv</i></div><div class=\"ori\">[ne<SUP>2</SUP>/-ve]</div><div class=\"def\"><num>①</num> しかも[また]...(し)ないように</div><div class=\"ex\"><i>quaeso ut advocatus mi adsis</i> ～ <i>abeas</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">頼むから弁護士として私のところにいてくれ, 帰らないでくれ.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>～...～</i><span class=\"ext\">...でもなく...でもないように.</span></div>\r\n","<div class=\"hw\">nēvis, nēvolt</div><div class=\"def\">《古形》=non vis, non vult(⇒ <a href=\"entry://nōlō\">nolo</a>).</div>\r\n","<div class=\"hw\">nēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://neō\">neo</a>.</div>\r\n","<div class=\"hw\">nī</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"ori\">[<i>cf. </i> ne<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> =<a href=\"entry://nē\">ne<SUP>2</SUP></a>.</div><div class=\"def\"><num>②</num> もし...でなければ(=<a href=\"entry://sī\">si non</a>, <a href=\"entry://nisi\">nisi</a>).</div>\r\n","<div class=\"hw\">Nīcaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーカエア, <SUP>*</SUP>-カイア《 (1) Bithynia の町;通称ニケーア;現 Iznik.(2) Locris の Thermopylae 近くの町.(3) India の町;Alexander 大王が建設した》.</div>\r\n","<div class=\"hw\">Nīcaeensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Nicaea (1) の.</div>\r\n","<div class=\"hw\">Nīcaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Juppiter の添え名として)勝利を与える.</div>\r\n","<div class=\"hw\">Nīcander</div><div class=\"pos\">-drī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーカンデル, <SUP>*</SUP>-ドロス《Colophon 出身のギリシアの詩人(前2世紀);Claros の Apollo の神官でもあった》.</div>\r\n","<div class=\"hw\">Nīciās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーキアース《Peloponnesus 戦争時の Athenae の政治家・将軍(前470?‐413);Sicilia 遠征軍を率いて出征したが, Syracusae 軍に敗れ処刑された》.</div>\r\n","<div class=\"hw\">Nīcoclēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーコクレース《Sicyon の僭主(前3世紀)》.</div>\r\n","<div class=\"hw\">Nīcolāus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーコラーウス, <SUP>*</SUP>-オス《Damascus 出身の逍遥学派哲学者(前1世紀)》</div><div class=\"ex\"><i>palma Nicolai</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">Nicolaus が Augustus 帝に寄贈した特大種のナツメヤシの木.</span></div>\r\n","<div class=\"hw\">Nīcomēdēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーコメーデース《Bithynia の数人の王;特に <i>Nicomedes IV Philopator</i>, 自らの王国をローマ人民に遺贈した(在位前94‐74)》.</div>\r\n","<div class=\"hw\">Nīcomēdīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーコメーディーア, <SUP>*</SUP>-デイア《Bithynia の首都;現 Izmit》.</div>\r\n","<div class=\"hw\">Nīcopolis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーコポリス《Epirus の町;Actium の海戦での勝利を記念して Augustus 帝が建設した》.</div>\r\n","<div class=\"hw\">Nīcātōr</div><div class=\"pos\">-oris, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(「勝利者」の意)</div><div class=\"def\"><num>①</num> Seleucus I の呼称.</div><div class=\"def\"><num>②</num> (<i>pl</i>)Macedonia の親衛隊の呼称.</div>\r\n","<div class=\"hw\">Nīcēphorium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ニーケーポリウム, <SUP>*</SUP>-オン《 (1) Pergamum 付近の森;Eumenes I が Antiochus I に対する勝利を記念して植樹した.(2) Mesopotamia の町》.</div>\r\n","<div class=\"hw\">Nīcēphorius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ニーケーポリウス《Armenia の川》.</div>\r\n","<div class=\"hw\">nīcētērium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">勝利の褒賞.</div>\r\n","<div class=\"hw\">nīdificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nidus/facio]</div><div class=\"def\">巣作りの.</div>\r\n","<div class=\"hw\">nīdificō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nidus/facio]</div><div class=\"def\">巣を作る.</div>\r\n","<div class=\"hw\">nīdor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">(熱い飲食物が立てる)湯気, 香り;(物が焼けるときの)強烈な匂い[臭気], 煙.</div>\r\n","<div class=\"hw\">nīdulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nīdus\">nīdus</a>]</div><div class=\"def\">(小さな)巣.</div>\r\n","<div class=\"hw\">nīdus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 巣.</div><div class=\"def\"><num>②</num> (巣の中の)ひな鳥.</div><div class=\"def\"><num>③</num> 箱.</div><div class=\"def\"><num>④</num> 住みか, 家.</div>\r\n","<div class=\"hw\">nīdāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[nidus]</div><div class=\"def\">巣を作る材料.</div>\r\n","<div class=\"hw\">nīl<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://nihil\">nihil<SUP>1</SUP></a>, <a href=\"entry://nihil\">nihil<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Nīliacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Nilus 川の.</div><div class=\"def\"><num>②</num> エジプトの.</div>\r\n","<div class=\"hw\">Nīligena</div><div class=\"pos\">-ae, <i>m</i>, <i>f</i></div><div class=\"ori\">[Nilus/gigno]</div><div class=\"def\">Nilus 河畔に生まれた者(=エジプト人).</div>\r\n","<div class=\"hw\">nīlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://nihilum\">nihilum<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Nīlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> ニールス, <SUP>*</SUP>ネイロス, <SUP>∥</SUP>ナイル《 (1) エジプトの大河.(2)  (1) の河神》.</div><div class=\"def\"><num>②</num> (n-)水路, 水道.</div>\r\n","<div class=\"hw\">nīmīrum</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ni/mirus]</div><div class=\"def\">確かに, もちろん, 当然.</div>\r\n","<div class=\"hw\">Nīreus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニーレウス《Troja 戦争における ギリシア軍中 Achilles に次ぐ美男子》.</div>\r\n","<div class=\"hw\">Nīsaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Nīsēius\">Niseius</a>.</div>\r\n","<div class=\"hw\">Nīsias</div><div class=\"pos\">-adis [-ados], <i>f</i></div><div class=\"def\">(「Megara の王 Nisus の後裔の女」の意)Sicilia 島の Megara Hyblaea(Megara の植民市)の女.</div>\r\n","<div class=\"hw\">nīsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">=<a href=\"entry://nixus\">nixus<SUP>1</SUP></a>(⇒ <a href=\"entry://nītor\">nitor<SUP>2</SUP></a>).</div><hr><div class=\"hw\">nīsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 踏みしめること.</div><div class=\"def\"><num>②</num> 力をこめること, 努力.</div><div class=\"def\"><num>③</num> よじ登ること;前進.</div><div class=\"def\"><num>④</num> 趨勢, 動向.</div>\r\n","<div class=\"hw\">Nīsus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ニースス, <SUP>*</SUP>-ソス《 (1) Megara の王;娘 Scylla に裏切られて死んだ.(2) Aeneas の部下の一人;親友 Euryalus とともに戦死した》.</div>\r\n","<div class=\"hw\">Nīsēis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Nisus の娘(=<a href=\"entry://Scylla\">Scylla</a>).</div>\r\n","<div class=\"hw\">Nīsēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nisus の</div><div class=\"ex\"><i>Niseia virgo</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Scylla\">Scylla</a>.</span></div>\r\n","<div class=\"hw\">nītibundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nitor<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> ...に頼って 〈+<i>abl</i>〉.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 圧倒する.</div>\r\n","<div class=\"hw\">nītor<SUP>2</SUP></div><div class=\"pos\">-tī nixus [nīsus] sum, <i>intr dep</i></div><div class=\"def\"><num>①</num> 寄りかかる, もたれる 〈re;in re;in alqd〉</div><div class=\"ex\"><i>niti genibus [genu</i>] (<author>L<small>IV</small> [S<small>UET</small>]</author>)<span class=\"ext\">ひざまずく.</span></div><div class=\"def\"><num>②</num> 支えられる, 立っている 〈re〉.</div><div class=\"def\"><num>③</num> 信頼する, 頼みにする 〈+<i>abl</i>〉.</div><div class=\"def\"><num>④</num> 基づく, 依存する 〈re〉.</div><div class=\"def\"><num>⑤</num> 力をこめる[ふりしぼる]</div><div class=\"ex\"><i>quantum...adstrictis faucibus niti poterat, clamitavit</i> (<author>T<small>AC</small></author>)<span class=\"ext\">首を綱で縛られたままでできる限り声をふりしぼって叫んだ.</span></div><div class=\"def\"><num>⑥</num> (骨折って)進む.</div><div class=\"def\"><num>⑦</num> (精いっぱい)努力[尽力]する 〈pro re [alqo];ut, ne〉.</div><div class=\"def\"><num>⑧</num> 争う 〈contra alqd〉.</div><div class=\"def\"><num>⑨</num> 得ようと努力する 〈ad [in] alqd;ut, ne;+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">nītēdula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘動〙ヤマネ(山鼠).</div>\r\n","<div class=\"hw\">nītēla<SUP>2</SUP>, nītella</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://nītēdula\">nitedula</a>.</div>\r\n","<div class=\"hw\">nītī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://nītor\">nitor<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">nīve</div><div class=\"pos\"><i>conj</i></div><div class=\"ori\">[ni/-ve]</div><div class=\"def\"><num>①</num> =<a href=\"entry://nēve\">neve</a>.</div><div class=\"def\"><num>②</num> それとも...でなければ.</div>\r\n","<div class=\"hw\">nīvit</div><div class=\"pos\">-ere, <i>intr impers</i></div><div class=\"def\">雪が降る.</div>\r\n","<div class=\"hw\">nō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> 泳ぐ.</div><div class=\"def\"><num>②</num> 浮かぶ, 漂う.</div><div class=\"def\"><num>③</num> 目まいがする.</div>\r\n","<div class=\"hw\">nōbilis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nosco]</div><div class=\"def\"><num>①</num> よく知られている.</div><div class=\"def\"><num>②</num> 高名な, 著名な;悪名高い.</div><div class=\"def\"><num>③</num> 高貴な, 家柄[生まれ]のよい, 貴族の.</div><div class=\"def\"><num>④</num> 気高い, 高潔な.</div><div class=\"def\"><num>⑤</num> 威厳のある, 堂々とした.</div><hr><div class=\"hw\">nōbilis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">高貴な家柄[生まれ]の者, 貴族.</div>\r\n","<div class=\"hw\">nōbiliter</div><div class=\"pos\"><i>adv</i>(<i>superl</i> nōbilissimē)</div><div class=\"ori\">[nobilis<SUP>1</SUP>]</div><div class=\"def\">すばらしく, みごとに.</div>\r\n","<div class=\"hw\">nōbilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[nobilis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 高名, 名声.</div><div class=\"def\"><num>②</num> 高貴な生まれ.</div><div class=\"def\"><num>③</num> 貴族(階級).</div><div class=\"def\"><num>④</num> 卓越, 優秀.</div><div class=\"def\"><num>⑤</num> 高潔, 気高さ.</div>\r\n","<div class=\"hw\">nōbilitātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nōbilitō\">nobilito</a>.</div>\r\n","<div class=\"hw\">nōbilitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nobilis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 広く知らせる, 注意を促す.</div><div class=\"def\"><num>②</num> 著名に[悪名高く]する.</div><div class=\"def\"><num>③</num> 高貴に[気高く]する.</div><div class=\"def\"><num>④</num> (文体に)光彩を与える.</div>\r\n","<div class=\"hw\">nōbīs</div><div class=\"pos\"><i>dat</i>, <i>abl</i></div><div class=\"def\">⇒<a href=\"entry://nōs\">nos</a>.</div>\r\n","<div class=\"hw\">nōbīscum</div><div class=\"def\">=cum nobis(⇒ <a href=\"entry://ego\">ego</a>).</div>\r\n","<div class=\"hw\">nōdulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://nōdus\">nōdus</a>]</div><div class=\"def\"><num>①</num> (小さな)結び目.</div><div class=\"def\"><num>②</num> こぶ, 節<SUB>ふし</SUB>.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙小(結)節.</div>\r\n","<div class=\"hw\">nōdus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 結び目.</div><div class=\"def\"><num>②</num> こぶ, 節<SUB>ふし</SUB>.</div><div class=\"def\"><num>③</num> 帯, ベルト.</div><div class=\"def\"><num>④</num> (髪の)ふさ, 束.</div><div class=\"def\"><num>⑤</num> きずな, 結びつき.</div><div class=\"def\"><num>⑥</num> 束縛, 拘束.</div><div class=\"def\"><num>⑦</num> 厄介な問題, 難事.</div>\r\n","<div class=\"hw\">nōdō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nodus]</div><div class=\"def\"><num>①</num> 結ぶ, 結び目をつくる.</div><div class=\"def\"><num>②</num> 節<SUB>ふし</SUB>だらけにする.</div>\r\n","<div class=\"hw\">nōdōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nodus]</div><div class=\"def\"><num>①</num> 結び目の多い.</div><div class=\"def\"><num>②</num> こぶ[節<SUB>ふし</SUB>]だらけの.</div><div class=\"def\"><num>③</num> (法律が)がんじがらめにする.</div><div class=\"def\"><num>④</num> もつれた, 紛糾した.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙結節(性)の.</div>\r\n","<div class=\"hw\">Nōla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ノーラ《Campania の町》.</div>\r\n","<div class=\"hw\">nōluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nōlō\">nolo</a>.</div>\r\n","<div class=\"hw\">Nōlānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nola の.</div>\r\n","<div class=\"hw\">nōlō</div><div class=\"pos\">nolle nōluī, <i>tr</i>, <i>intr irreg</i></div><div class=\"ori\">[ne-/volo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 欲しない, 好まない, 拒絶する 〈alqd;+<i>inf</i>;+<i>acc c. inf</i>;ut;+<i>subj</i>〉.</div><div class=\"def\"><num>②</num> (<i>impr</i> で)(禁止)...するな, ...してはいけない 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">nōmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[<i>cf. </i> nosco, cognomen]</div><div class=\"def\"><num>①</num> 名, 名前</div><div class=\"ex\">(<i>dat</i> とともに)～ <i>Mercurio est mihi</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私の名は Mercurius だ</span></div><div class=\"ex\"><i>suo nomine</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自分の名において(=自分の責任で, 独立で)</span></div><div class=\"ex\"><i>per</i> ～ (<author>C<small>IC</small></author>) =<i>nomine</i> (<author>C<small>IC</small></author>) 〈+<i>gen</i>〉<span class=\"ext\">(宣誓などにおいて)...の名にかけて.</span></div><div class=\"def\"><num>②</num> 名称, 呼称;称号.</div><div class=\"def\"><num>③</num> 表現, ことば</div><div class=\"ex\"><i>uno nomine</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一言でいえば, 要するに.</span></div><div class=\"def\"><num>④</num> 〘文〙名詞.</div><div class=\"def\"><num>⑤</num> 名声, 評判.</div><div class=\"def\"><num>⑥</num> 見せかけ;口実.</div><div class=\"def\"><num>⑦</num> (実体に対して)名目.</div><div class=\"def\"><num>⑧</num> (ある名前をもつ)人, 国民, 民族</div><div class=\"ex\"><i>filii regis, nomina tanta</i> (<author>L<small>IV</small></author>)<span class=\"ext\">王の息子たちというこのように偉大な人たち</span></div><div class=\"ex\">～ <i>Romanum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ローマ人[国民, 軍].</span></div><div class=\"def\"><num>⑨</num> 氏族名《ときに cognomen または praenomen を指す》.</div><div class=\"def\"><num>⑩</num> (名簿・帳簿などに記入された)名前</div><div class=\"ex\">～ <i>dare</i> [<i>edere</i>] (<author>C<small>IC</small></author>)<span class=\"ext\">兵隊名簿に登録する, 徴募に応ずる</span></div><div class=\"ex\">～ <i>alcis deferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を提訴する</span></div><div class=\"ex\"><i>nomina solvere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">借金を支払う.</span></div><div class=\"def\"><num>⑪</num> 見出し, 範疇.</div><div class=\"def\"><num>⑫</num> 理由, 目的, 根拠.</div>\r\n","<div class=\"hw\">nōmenclātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://nōmen\">nōmen</a>/calo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 名前を呼ぶこと.</div><div class=\"def\"><num>②</num> (名前の)一覧表, リスト.</div>\r\n","<div class=\"hw\">nōmenclātor, -culātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[nomen/calo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 名前を呼ぶ者.</div><div class=\"def\"><num>②</num> 名告げ奴隷《主人に付き添って, 出会う人の名を主人に告げた》.</div>\r\n","<div class=\"hw\">nōmenclātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nomen/calo<SUP>1</SUP>]</div><div class=\"def\">命名(法);(事物の)名前を述べること.</div>\r\n","<div class=\"hw\">Nōmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ノーメントゥム《Latium 北部の町;現 Mentana》.</div>\r\n","<div class=\"hw\">Nōmentānus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ノーメンターヌス《ローマ人の家名》.</div><hr><div class=\"hw\">Nōmentānus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nomentum の.</div>\r\n","<div class=\"hw\">nōmine</div><div class=\"pos\"><i>abl</i></div><div class=\"def\">⇒<a href=\"entry://nōmen\">nomen</a>.</div>\r\n","<div class=\"hw\">nōminitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://nōminō\">nōminō</a>]</div><div class=\"def\">(...を...と)名づける, 呼ぶ 〈+2個の <i>acc</i>〉.</div>\r\n","<div class=\"hw\">nōminālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://nōminālis\">nōminālis</a>]</div><div class=\"def\">(子供の)命名日.</div>\r\n","<div class=\"hw\">nōminālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nomen]</div><div class=\"def\">名前の[に属する].</div>\r\n","<div class=\"hw\">nōminātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[nomino]</div><div class=\"def\"><num>①</num> 名指して.</div><div class=\"def\"><num>②</num> 特別に, わざわざ.</div>\r\n","<div class=\"hw\">nōminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nomino]</div><div class=\"def\"><num>①</num> 命名.</div><div class=\"def\"><num>②</num> 名称, 呼称.</div><div class=\"def\"><num>③</num> 指名, 任命.</div>\r\n","<div class=\"hw\">nōminātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nōminō\">nomino</a>.</div><hr><div class=\"hw\">nōminātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">〘文〙名詞.</div>\r\n","<div class=\"hw\">nōminātīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nomino]</div><div class=\"ex\"><i>casus ～</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">〘文〙主格.</span></div>\r\n","<div class=\"hw\">nōminō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[nomen]</div><div class=\"def\"><num>①</num> 名づける, 呼ぶ;(<i>pass</i>)...と呼ばれる, ...という名である.</div><div class=\"def\"><num>②</num> 名前を呼ぶ.</div><div class=\"def\"><num>③</num> 名を挙げる, 言及する.</div><div class=\"def\"><num>④</num> 指名する, 任命する.</div><div class=\"def\"><num>⑤</num> 詳述する.</div><div class=\"def\"><num>⑥</num> 糾弾[告発]する.</div><div class=\"def\"><num>⑦</num> 数に入れる, 一つとみなす 〈in+<i>abl</i>;inter+<i>acc</i>〉.</div><div class=\"def\"><num>⑧</num> (<i>pass</i>)有名である.</div>\r\n","<div class=\"hw\">nōn</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[noenum]</div><div class=\"def\"><num>①</num> ...でない</div><div class=\"ex\"><i>et [ac] ～</i><span class=\"ext\">そして...ない(むしろ)</span></div><div class=\"ex\">(否定辞が後に付いて弱い否定を表わす)<i>～ numquam</i><span class=\"ext\">時には, 時々</span></div><div class=\"ex\">(否定辞が前に付いて強い否定を表わす)<i>numquam ～</i><span class=\"ext\">常に, いつも.</span></div><div class=\"def\"><num>②</num> =<a href=\"entry://nē\">ne<SUP>2</SUP></a>.</div><div class=\"def\"><num>③</num> =<a href=\"entry://nōnne\">nonne</a>.</div><div class=\"def\"><num>④</num> (否定の答として)いいえ, 否.</div>\r\n","<div class=\"hw\">nōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[nonus]</div><div class=\"def\"><num>①</num> (<i>sc. </i> hora)(一日の)第9時《今の午後3時頃;ローマ市ではこの時刻に仕事を終えた》.</div><div class=\"def\"><num>②</num> (N-)〘神話〙ノーナ《妊娠の9か月目をつかさどる女神;運命の三女神 Parcae のうちの一人ともみなされた》.</div>\r\n","<div class=\"hw\">Nōnacris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ノーナクリス《Arcadia の山と町》.</div>\r\n","<div class=\"hw\">Nōnacrīnus, -crius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nonacris の;Arcadia の.</div>\r\n","<div class=\"hw\">Nōnae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[nonus]</div><div class=\"def\">(3・5・7・10月の)第7日, (他の月の)第5日《Idus を1日目と数えて逆算した9日目》.</div>\r\n","<div class=\"hw\">nōndum</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[non/dum<SUP>2</SUP>]</div><div class=\"def\">まだ...ない.</div>\r\n","<div class=\"hw\">nōngentiēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://nōngentī\">nōngentī</a>]</div><div class=\"def\">900回[倍].</div>\r\n","<div class=\"hw\">nōngentēsimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[↓<a href=\"entry://nōngentī\">nōngentī</a>]</div><div class=\"def\">900番目の.</div>\r\n","<div class=\"hw\">nōngentī</div><div class=\"pos\">-ae -a, <i>num card</i></div><div class=\"ori\">[novem/centum]</div><div class=\"def\">900(の).</div>\r\n","<div class=\"hw\">nōningentī</div><div class=\"pos\">-ae -a, <i>num card</i></div><div class=\"def\">=<a href=\"entry://nōngentī\">nongenti</a>.</div>\r\n","<div class=\"hw\">Nōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ノーニウス《ローマ人の氏族名;特に (1) <i>M. ～ Suffenas</i>, 法務官(前52?).(2) <i>～ Marcellus</i>, 4世紀の百科全書的な辞書の編者》.</div>\r\n","<div class=\"hw\">nōnne</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[non/-ne]</div><div class=\"def\"><num>①</num> (肯定の答を予期する疑問文を導いて)...(では)ないか.</div><div class=\"def\"><num>②</num> (間接疑問を導いて)...かどうか.</div>\r\n","<div class=\"hw\">nōnnihil, nōn nihil</div><div class=\"pos\"><i>indecl n, adv</i></div><div class=\"def\">⇒<a href=\"entry://nihil\">nihil<SUP>1</SUP></a>, <a href=\"entry://nihil\">nihil<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">nōnnisi, nōn nisi</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">⇒<a href=\"entry://nisi\">nisi</a>.</div>\r\n","<div class=\"hw\">nōnnullus, nōn nullus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">⇒<a href=\"entry://nullus\">nullus</a>.</div>\r\n","<div class=\"hw\">nōnnumquam, -nunquam, nōn numquam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">⇒<a href=\"entry://numquam\">numquam</a>.</div>\r\n","<div class=\"hw\">nōnnusquam, nōn nusquam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">⇒<a href=\"entry://nusquam\">nusquam</a>.</div>\r\n","<div class=\"hw\">nōnnēmō, nōn nēmō</div><div class=\"pos\">-inis, <i>m</i></div><div class=\"def\">⇒<a href=\"entry://nēmō\">nemo</a>.</div>\r\n","<div class=\"hw\">nōnus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[novem]</div><div class=\"def\">第9の, 9番目の.</div>\r\n","<div class=\"hw\">nōnusdecimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[↑<a href=\"entry://nōnus\">nōnus</a>/decimus]</div><div class=\"def\">第19の, 19番目の.</div>\r\n","<div class=\"hw\">nōnāgintā</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"ori\">[nonus]</div><div class=\"def\">90(の).</div>\r\n","<div class=\"hw\">nōnāgiēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nōnāgintā\">nōnāgintā</a>]</div><div class=\"def\">90回[倍].</div>\r\n","<div class=\"hw\">nōnāgēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nōnāgēnī\">nōnāgēnī</a>]</div><div class=\"def\"><num>①</num> 90からなる.</div><div class=\"def\"><num>②</num> 90歳の.</div>\r\n","<div class=\"hw\">nōnāgēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[nonaginta]</div><div class=\"def\">90ずつの.</div>\r\n","<div class=\"hw\">nōnāgēsimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[nonaginta]</div><div class=\"def\">第90の, 90番目の.</div>\r\n","<div class=\"hw\">nōnānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nonus]</div><div class=\"def\">第9軍団の.</div>\r\n","<div class=\"hw\">nōnānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://nōnānus\">nōnānus</a>]</div><div class=\"def\">第9軍団の兵士たち.</div>\r\n","<div class=\"hw\">Nōra</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ノーラ《 (1) Cappadocia の要塞.(2) Sardinia 島の町.(3) India の町》.</div>\r\n","<div class=\"hw\">nōram</div><div class=\"pos\"><i>plpf</i></div><div class=\"def\">=noveram(⇒ <a href=\"entry://noscō\">nosco</a>).</div>\r\n","<div class=\"hw\">Nōrensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Nora (2) の住民.</div>\r\n","<div class=\"hw\">Nōricum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ノーリクム, <SUP>*</SUP>-コン《Danubius 川の南, Raetia と Pannonia の間の地域;のちにローマの属州》.</div>\r\n","<div class=\"hw\">Nōricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Noricum の.</div>\r\n","<div class=\"hw\">nōrim</div><div class=\"pos\"><i>subj pf</i></div><div class=\"def\">=noverim(⇒ <a href=\"entry://noscō\">nosco</a>).</div>\r\n","<div class=\"hw\">Nōrēia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ノーレイヤ, <SUP>*</SUP>-レーイアー《Noricum の町》.</div>\r\n","<div class=\"hw\">nōs</div><div class=\"pos\"><i>pron pl</i></div><div class=\"def\">我々, 私たち(⇒ <a href=\"entry://ego\">ego</a>).</div>\r\n","<div class=\"hw\">nōsmet</div><div class=\"pos\"><i>pron pers</i></div><div class=\"ori\">[nos/-met]</div><div class=\"def\">《強意形》我々自身.</div>\r\n","<div class=\"hw\">nōtescō</div><div class=\"pos\">-ere nōtuī, <i>intr inch</i></div><div class=\"ori\">[notus]</div><div class=\"def\">知られるようになる.</div>\r\n","<div class=\"hw\">nōtificō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[notus/facio]</div><div class=\"def\">知らせる.</div>\r\n","<div class=\"hw\">nōtitia</div><div class=\"pos\">-ae, <B>-ēs</B> -ēī, <i>f</i></div><div class=\"ori\">[notus]</div><div class=\"def\"><num>①</num> 知り合いになること, 面識.</div><div class=\"def\"><num>②</num> 知って[気づいて]いること.</div><div class=\"def\"><num>③</num> 熟知, 精通.</div><div class=\"def\"><num>④</num> (学問・言語などの)知識, 理解.</div><div class=\"def\"><num>⑤</num> 概念, 観念.</div><div class=\"def\"><num>⑥</num> 名声, 評判;悪評, 悪名.</div>\r\n","<div class=\"hw\">nōtiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nosco]</div><div class=\"def\"><num>①</num> 知り合いになること, 面識.</div><div class=\"def\"><num>②</num> 査察, 査問, 取調べ.</div><div class=\"def\"><num>③</num> 概念, 観念.</div>\r\n","<div class=\"hw\">nōtopodium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙背枝.</div>\r\n","<div class=\"hw\">nōtor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[nosco]</div><div class=\"def\">保証人.</div>\r\n","<div class=\"hw\">nōtum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙胸背板.</div>\r\n","<div class=\"hw\">nōtus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[nosco]</div><div class=\"def\"><num>①</num> 知られた, 既知の</div><div class=\"ex\"><i>tibi causam notam esse volui</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたに事実を知ってほしかった.</span></div><div class=\"def\"><num>②</num> 知り合いの.</div><div class=\"def\"><num>③</num> 周知の, 知れわたっている;有名な;悪名高い.</div><div class=\"def\"><num>④</num> 慣れた, おなじみの</div><div class=\"ex\"><i>nota palus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">住みなれた沼地.</span></div>\r\n","<div class=\"hw\">nōtuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://nōtescō\">notesco</a>.</div>\r\n","<div class=\"hw\">nōtī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[notus]</div><div class=\"def\">友人, 知人.</div>\r\n","<div class=\"hw\">nōtōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nōtōrius\">nōtōrius</a>]</div><div class=\"def\"><num>①</num> 密告.</div><div class=\"def\"><num>②</num> 告訴状.</div>\r\n","<div class=\"hw\">nōtōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[notor]</div><div class=\"def\"><num>①</num> 知らせる.</div><div class=\"def\"><num>②</num> 公然の, 周知の.</div>\r\n","<div class=\"hw\">nōvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://noscō\">nosco</a>.</div>\r\n","<div class=\"hw\">nūbifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nūbēs\">nūbēs</a>/fero]</div><div class=\"def\"><num>①</num> 雲を頂いた.</div><div class=\"def\"><num>②</num> 雲をもたらす.</div>\r\n","<div class=\"hw\">nūbigena</div><div class=\"pos\">-ae, <i>adj m</i></div><div class=\"ori\">[nubes/gigno]</div><div class=\"def\">雲から生まれた《Centaurus 族または Phrixus を指す》.</div>\r\n","<div class=\"hw\">nūbilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[nubo]</div><div class=\"def\">結婚適齢期の.</div>\r\n","<div class=\"hw\">nūbilum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nūbilus\">nūbilus</a>]</div><div class=\"def\"><num>①</num> 曇天.</div><div class=\"def\"><num>②</num> (<i>pl</i>)雲.</div>\r\n","<div class=\"hw\">nūbilus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nubes]</div><div class=\"def\"><num>①</num> 雲におおわれた, 曇った;雲をもたらす.</div><div class=\"def\"><num>②</num> 暗い.</div><div class=\"def\"><num>③</num> (気が)ふさいだ, 憂鬱な.</div><div class=\"def\"><num>④</num> 恵まれない, 不運な.</div>\r\n","<div class=\"hw\">nūbilō</div><div class=\"pos\">-āre -āvī, <i>intr</i></div><div class=\"ori\">[nubilum]</div><div class=\"def\">曇っている;(<i>impers pass</i>)曇る.</div>\r\n","<div class=\"hw\">nūbilōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://nūbilum\">nūbilum</a>]</div><div class=\"def\">曇った.</div>\r\n","<div class=\"hw\">nūbēcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://nūbēs\">nūbēs</a>]</div><div class=\"def\"><num>①</num> (小さな)雲.</div><div class=\"def\"><num>②</num> (表情の)曇り.</div><div class=\"def\"><num>③</num> (雲のような)よごれ, しみ.</div>\r\n","<div class=\"hw\">nūbēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 雲.</div><div class=\"def\"><num>②</num> 群れ, 大群.</div><div class=\"def\"><num>③</num> (一面の)ほこり, 煙.</div><div class=\"def\"><num>④</num> おおい, ベール.</div><div class=\"def\"><num>⑤</num> (表情の)曇り.</div><div class=\"def\"><num>⑥</num> 不安, 悲しみ.</div><div class=\"def\"><num>⑦</num> (戦争・災難などの)脅威, 暗雲.</div>\r\n","<div class=\"hw\">nūbō</div><div class=\"pos\">-ere nupsī nuptum, <i>intr</i></div><div class=\"ori\">[nubes]</div><div class=\"def\">(女が)結婚する 〈alci〉;とつぐ 〈in+<i>acc</i>〉</div><div class=\"ex\"><i>in familiam clarissimam nubere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">各家にとつぐ.</span></div>\r\n","<div class=\"hw\">Nūceria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ヌーケリア《 (1) Campania 南部の町.(2) Umbria の町》.</div>\r\n","<div class=\"hw\">Nūcerīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Nuceria (1) の.</div>\r\n","<div class=\"hw\">nūditās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[nudus]</div><div class=\"def\">裸, むきだし.</div>\r\n","<div class=\"hw\">nūdus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 裸の, 衣服を着けていない, むきだしの.</div><div class=\"def\"><num>②</num> 武装していない;攻撃にさらされた, 無防備の.</div><div class=\"def\"><num>③</num> おおいのない.</div><div class=\"def\"><num>④</num> (剣が)さやから抜かれた, 抜身の.</div><div class=\"def\"><num>⑤</num> 葉[木]のない;毛のない.</div><div class=\"def\"><num>⑥</num> 飾りのない, 簡素な.</div><div class=\"def\"><num>⑦</num> 空<SUB>から</SUB>の.</div><div class=\"def\"><num>⑧</num> (...を)奪われた, (...が)欠けている 〈+<i>abl [gen</i>]〉.</div><div class=\"def\"><num>⑨</num> 貧乏な, 無一文の.</div><div class=\"def\"><num>⑩</num> 単なる, ただの, 全くの</div><div class=\"ex\"><i>hoc nudum relinquitur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ただこれだけが残される.</span></div><div class=\"def\"><num>⑪</num> (態度・表現などが)あからさまな.</div>\r\n","<div class=\"hw\">nūdātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nudo]</div><div class=\"def\">裸にすること, 露出.</div>\r\n","<div class=\"hw\">nūdō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://nūdus\">nūdus</a>]</div><div class=\"def\"><num>①</num> 裸にする, 脱がせる;(剣を)抜く.</div><div class=\"def\"><num>②</num> はぐ, むく.</div><div class=\"def\"><num>③</num> むきだしにする, あらわにする.</div><div class=\"def\"><num>④</num> 攻撃にさらす, 無防備にする.</div><div class=\"def\"><num>⑤</num> 奪う, 略奪する 〈alqd re〉.</div><div class=\"def\"><num>⑥</num> 暴露する, あばく.</div>\r\n","<div class=\"hw\">nūgae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\"><num>①</num> むだな[ばかげた]こと[もの].</div><div class=\"def\"><num>②</num> 悪ふざけ, 冗談.</div><div class=\"def\"><num>③</num> おどけ者, ひょうきん者.</div>\r\n","<div class=\"hw\">nūgax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[nugor]</div><div class=\"def\">無能な, 役立たずの.</div>\r\n","<div class=\"hw\">nūgigerulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[nugae/gero]</div><div class=\"def\">=<a href=\"entry://nūgivendus\">nugivendus</a>.</div>\r\n","<div class=\"hw\">nūgivendus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[nugae/vendo]</div><div class=\"def\">安ぴか物の行商人.</div>\r\n","<div class=\"hw\">nūgor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[nugae]</div><div class=\"def\"><num>①</num> ふざける.</div><div class=\"def\"><num>②</num> だます, かつぐ.</div>\r\n","<div class=\"hw\">nūgācitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nūgae\">nūgae</a>]</div><div class=\"def\">悪ふざけ, 冗談.</div>\r\n","<div class=\"hw\">nūgālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nūgae\">nūgae</a>]</div><div class=\"def\">くだらない, つまらない, 取るに足らない.</div>\r\n","<div class=\"hw\">nūgātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[nugor]</div><div class=\"def\"><num>①</num> ふざける人, ばかなまねをする人.</div><div class=\"def\"><num>②</num> 作り話をする人, ほら吹き.</div>\r\n","<div class=\"hw\">nūgātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nugator]</div><div class=\"def\">むだな, ばかげた, 取るに足らない.</div>\r\n","<div class=\"hw\">nūgātōriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://nūgātōrius\">nūgātōrius</a>]</div><div class=\"def\">軽率に, ふまじめに.</div>\r\n","<div class=\"hw\">nūmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[nuto]</div><div class=\"def\"><num>①</num> うなずき;指図, 意向.</div><div class=\"def\"><num>②</num> 権能, 威光.</div><div class=\"def\"><num>③</num> 神意.</div><div class=\"def\"><num>④</num> 神性.</div><div class=\"def\"><num>⑤</num> 神.</div>\r\n","<div class=\"hw\">nūmu-</div><div class=\"def\">⇒nummu-.</div>\r\n","<div class=\"hw\">nūper</div><div class=\"pos\"><i>adv</i>(<i>sup</i> nūperrimē)</div><div class=\"ori\">[nu-(<i>cf</i>. nunc)/-per(<i>cf</i>. semper)]</div><div class=\"def\"><num>①</num> 最近, 少し前に.</div><div class=\"def\"><num>②</num> 近年, 昨今.</div>\r\n","<div class=\"hw\">nūperus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nūper\">nūper</a>]</div><div class=\"def\">新着[新来]の.</div>\r\n","<div class=\"hw\">nūtrior</div><div class=\"pos\">-īrī -ītus sum, <i>tr dep</i></div><div class=\"def\">=<a href=\"entry://nūtriō\">nutrio</a>.</div>\r\n","<div class=\"hw\">nūtrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[nutrio]</div><div class=\"def\"><num>①</num> 乳母, 養育者《女性》.</div><div class=\"def\"><num>②</num> (<i>pl</i>)(女性の)乳房.</div><div class=\"def\"><num>③</num> 促進[助長]するもの.</div>\r\n","<div class=\"hw\">nūtriō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i></div><div class=\"def\"><num>①</num> 授乳する.</div><div class=\"def\"><num>②</num> 滋養物を与える.</div><div class=\"def\"><num>③</num> 育てる, 養育する.</div><div class=\"def\"><num>④</num> 育成[助長, 促進]する.</div><div class=\"def\"><num>⑤</num> 世話[手当て]する.</div>\r\n","<div class=\"hw\">nūtrīcia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[nutricius<SUP>2</SUP>]</div><div class=\"def\">養育者《女性》.</div>\r\n","<div class=\"hw\">nūtrīcium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://nūtrīcius\">nūtrīcius<SUP>1</SUP>, -tius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 育てること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(<i>pl</i>)(乳母に与える)養育料.</div>\r\n","<div class=\"hw\">nūtrīcius<SUP>1</SUP>, -tius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[nutrix, nutrio]</div><div class=\"def\">養育者のような.</div><hr><div class=\"hw\">nūtrīcius<SUP>2</SUP>, -tius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">養い親;守り役, 師傅<SUB>しふ</SUB>.</div>\r\n","<div class=\"hw\">nūtrīciō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[nutrix]</div><div class=\"def\">《碑》養い親.</div>\r\n","<div class=\"hw\">nūtrīcor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[nutrix]</div><div class=\"def\"><num>①</num> 授乳する.</div><div class=\"def\"><num>②</num> 育てる, 養育する.</div><div class=\"def\"><num>③</num> 大事にする, 世話する.</div>\r\n","<div class=\"hw\">nūtrīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[nutrix]</div><div class=\"def\"><num>①</num> 乳母.</div><div class=\"def\"><num>②</num> 養育者《女性》.</div>\r\n","<div class=\"hw\">nūtrīcātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[nutricor]</div><div class=\"def\"><num>①</num> 乳を与えること, 授乳.</div><div class=\"def\"><num>②</num> 育てること.</div>\r\n","<div class=\"hw\">nūtrīcātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[nutricor]</div><div class=\"def\">育てること.</div>\r\n","<div class=\"hw\">nūtrīcō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">=<a href=\"entry://nūtrīcor\">nutricor</a>.</div>\r\n","<div class=\"hw\">nūtrīficō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[nutrix/facio]</div><div class=\"def\">授乳する.</div>\r\n","<div class=\"hw\">nūtrīmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[nutrio]</div><div class=\"def\">滋養物.</div>\r\n","<div class=\"hw\">nūtrīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://nūtrīmen\">nūtrīmen</a>]</div><div class=\"def\"><num>①</num> 滋養物, 食物.</div><div class=\"def\"><num>②</num> 養育.</div>\r\n","<div class=\"hw\">nūtrītius<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://nūtrīcius\">nutricius<SUP>1</SUP></a>, <a href=\"entry://nūtrīcius\">nutricius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">nūtrītiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[nutrio]</div><div class=\"def\">滋養物を与えること.</div>\r\n","<div class=\"hw\">nūtrītor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[nutrio]</div><div class=\"def\"><num>①</num> 滋養物を与える者.</div><div class=\"def\"><num>②</num> 育てる人, 養育者.</div>\r\n","<div class=\"hw\">nūtrītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://nūtriō\">nutrio</a>, <a href=\"entry://nūtrior\">nutrior</a>.</div>\r\n","<div class=\"hw\">nūtrītōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://nūtrītor\">nūtrītor</a>]</div><div class=\"def\"><num>①</num> 栄養になる.</div><div class=\"def\"><num>②</num> 育てる.</div>\r\n","<div class=\"hw\">nūtrītūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://nūtrīcātus\">nutricatus</a>.</div>\r\n","<div class=\"hw\">nūtus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[<SUP>*</SUP>nuo(<i>cf</i>. annuo);<i>cf</i>. nuto]</div><div class=\"def\"><num>①</num> (特に同意を表わす)うなずき.</div><div class=\"def\"><num>②</num> 沈下, 重力作用.</div><div class=\"def\"><num>③</num> (打撃をかわすため, または疲れて)頭を下げること.</div><div class=\"def\"><num>④</num> 命令, 指図, 意向.</div>\r\n","<div class=\"hw\">nūtātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://nūtō\">nūtō</a>]</div><div class=\"def\"><num>①</num> うなずくこと.</div><div class=\"def\"><num>②</num> 揺れ, ぐらつき.</div>\r\n","<div class=\"hw\">nūtō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[<SUP>*</SUP>nuo(<i>cf</i>. annuo)]</div><div class=\"def\"><num>①</num> うなずく.</div><div class=\"def\"><num>②</num> 傾く, たわむ.</div><div class=\"def\"><num>③</num> 揺らぐ, 揺れる.</div><div class=\"def\"><num>④</num> ぐらつく, よろめく.</div><div class=\"def\"><num>⑤</num> ためらう, 迷う.</div>\r\n"]);
